-- Gerado automaticamente por scripts/generate-seed.mjs a partir de seed/data/job_powers.json
-- Não editar manualmente.

INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('CAÇADOR DE TESOUROS', 'Quando seu grupo se aventura pelo mapa do mundo, você faz uma descoberta se tirar (NP + 1) ou menos no teste de Viagem (em vez de apenas 1).', 'common', 0, 2, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('COMPANHEIRO FIEL', 'Com a ajuda do grupo, crie um NPC construto, elemental, fera ou planta de nível 5 para ser seu companheiro: essa criatura não tem iniciativa e não sobe de nível, pode ter no máximo dois ataques básicos, recebe um bônus em testes de Precisão e Magia igual a (NP) e seus PV máximos são iguais a ((NP x o dado básico de Vigor do companheiro) + metade do seu nível). Você pode gastar sua ação para fazê-lo realizar uma ação no seu turno (uma vez por turno) — ele não age de outra forma. Se o seu companheiro for afetado por efeitos de turno, ele é afetado no seu turno. Seu companheiro entra e sai de cena com você e recebe os mesmos benefícios de descanso. Se ficar com 0 PV, ele foge e reencontra você no início da próxima cena em que estiver. Quando reaparece, está com metade dos PV máximos.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('PAPO DE TAVERNA', 'Ao descansar em uma estalagem ou taverna, você pode fazer (NP) perguntas ao mestre sobre os arredores e habitantes. O mestre deve responder com informações verdadeiras, mas você deve descrever como obteve tais informações.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('PRÁTICO', 'Você recupera (NP) PI após cada teste de Viagem.', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('VIAJANTE EXPERIENTE', 'Você reduz o dado rolado em seus testes de Viagem em um (mínimo d6). Se mais de um personagem tiver este poder, os efeitos não são cumulativos.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ARCANISMO RITUALISTA', 'Você pode fazer rituais da disciplina arcanismo, desde que seus efeitos estejam entre os domínios de um ou mais Arcanos que você vinculou. Rituais de arcanismo usam (VON + VON) no teste de Magia.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ARCANO EMERGENCIAL', 'Enquanto estiver em crise, o custo de invocar seu Arcano é reduzido em (NP × 5).', 'common', 0, 6, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('CÍRCULO ARCANO', 'Em seu turno, após dispensar voluntariamente um Arcano durante um conflito, se esse Arcano não foi invocado durante esse mesmo turno e você tem uma arma arcana equipada, você pode fazer a ação Feitiço sem usar uma ação (após resolver o efeito gerado por dispensar). O feitiço que você lançar dessa forma deve ter um custo total de PM igual ou inferior a (NP × 5) e você ainda deve pagar seu custo em PM.', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('REGENERAÇÃO ARCANA', 'Ao invocar um Arcano, você recupera (NP × 5) PV.', 'common', 0, 2, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('VINCULAR E INVOCAR', 'Você pode vincular Arcanos à sua alma para invocá-los em um momento posterior. Na primeira vez que você encontrar o Arcano em questão, o mestre lhe dirá os detalhes que envolvem cada processo de vinculação. Você pode usar uma ação e gastar 40 PM para invocar um Arcano que já vinculou. Se escolher este poder na criação de personagem, você começa o jogo já vinculado a um Arcano, à sua escolha, da lista nas próximas páginas. Para além disso, só se pode obter novos Arcanos explorando e avançando na história.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('BARRAGEM', 'Ao fazer um ataque à distância, você pode gastar 10 PM para escolher uma opção: o ataque recebe a propriedade multi (2); ou você aumenta em +1 a propriedade multi do ataque, até o máximo de multi (3).', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('FOGO CRUZADO', 'Quando uma criatura que você possa ver faz um ataque à distância, você pode gastar um total de PM igual a (5 + teste de Precisão da criatura alvo) para fazer o ataque falhar automaticamente contra todos os alvos. Você só pode usar este poder se tiver uma arma à distância equipada. Este poder não funciona se o teste de Precisão da criatura for um sucesso crítico.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('MAESTRIA COM ARMAS À DISTÂNCIA', 'Você recebe um bônus igual a (NP) em testes de Precisão à distância.', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('OLHOS DE ÁGUIA', 'Quando faz a ação Guarda, se escolher não dar cobertura a outra criatura, você pode escolher uma opção: o próximo ataque à distância que você fizer na cena atual causa (NP × 3) pontos de dano adicional ou você pode fazer um ataque livre com um arco ou arma de fogo equipada, considerando sua RA como 0 ao calcular o dano causado por este ataque.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('TIRO DE AVISO', 'Depois de atingir um ou mais alvos com um ataque à distância, você pode escolher não causar dano. Se fizer isso, escolha uma opção: cada alvo atingido pelo ataque fica abalado; ou fica lento; ou perde (NP × 10) PM. Descreva como você faz essa manobra!', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ARTILHARIA MÁGICA', 'Quando lança um feitiço ofensivo com uma arma arcana equipada, você recebe um bônus igual a (NP × 2) no teste de Magia.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('CATACLISMO', 'Quando lança um feitiço de duração “instantânea” com uma arma arcana equipada, você pode aumentar o custo total de PM do feitiço em até (NP × 10) PM. Se o fizer, o feitiço causa 5 pontos de dano adicional para cada 10 PM com os quais o custo foi aumentado dessa forma.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ELEMENTALISMO RITUALISTA', 'Você pode fazer rituais da disciplina elementalismo. Rituais de elementalismo usam (AST + VON) no teste de Magia.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('LÂMINA MÁGICA', 'Quando lança um feitiço ofensivo com custo total de PM igual ou inferior a (NP × 20) cujo alvo é uma única criatura, você pode escolher uma arma equipada que não seja arcana. Se fizer isso, seu teste de Magia usa a mesma fórmula do teste de Precisão da arma. Se a fórmula inclui Destreza, você também recebe um bônus igual ao (NP) no teste de Magia.', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('MAGIA ELEMENTAL', 'Sempre que adquirir este poder, aprenda um feitiço de Elementalista. Feitiços ofensivos de Elementalista usam (AST + VON) no teste de Magia.', 'common', 0, 10, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ABSORVER PM', 'Depois de sofrer dano, você recupera (NP × 2) PM.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ENTROPISMO RITUALISTA', 'Você pode fazer rituais da disciplina entropismo. Rituais de entropismo usam (AST + VON) no teste de Magia.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('MAGIA ENTRÓPICA', 'Sempre que adquirir este poder, aprenda um feitiço de Entropista. Feitiços ofensivos de Entropista usam (AST + VON) no teste de Magia.', 'common', 0, 10, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('SETE DA SORTE', 'Você tem um número da sorte; no início de cada sessão, esse número é 7. Uma vez por cena, após fazer um teste, você pode substituir o valor de um dado que rolou pelo seu número da sorte (mesmo que isso lhe dê um resultado impossível, como um 7 em um d6). Se fizer isso, o valor substituído torna-se o seu novo número da sorte.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('TEMPO ROUBADO', 'Durante um conflito, você pode usar uma ação e até (NP × 5) PM para interferir no fluxo temporal. Para cada 5 PM gastos dessa forma, escolha uma opção: uma criatura fica lenta; ou deixa de ficar lenta; ou faz a ação Equipamento sem custo; ou um inimigo que esteja lento perde (10 + (NP x 5)) Pontos de Vida; ou escolha um aliado que ainda não tenha agido nesta rodada: esse aliado faz o turno dele imediatamente depois do seu durante essa rodada. Cada opção só pode ser escolhida uma vez por uso deste poder e você precisa ver as criaturas para poder afetá-las com ele.', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ANÁLISE RÁPIDA', 'No início de um conflito, você pode gastar até (NP × 5) PM. Para cada 5 PM gastos dessa forma, escolha uma opção: escolha uma criatura que você possa ver e o mestre revela um dos Traços dela; ou escolha um tipo de dano e uma criatura que você possa ver e o mestre revela a Afinidade dela ao tipo escolhido.', 'common', 0, 6, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('CONCENTRADO', 'Aumente permanentemente seus PM máximos em (NP × 3). Ao fazer um teste aberto usando (AST + AST), você recebe um bônus igual a (NP) naquele teste (funciona apenas em testes abertos).', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('CONHECIMENTO É PODER', 'Quando faz um teste de Precisão, você pode substituir um de seus dados de Atributo por Astúcia (como (AST + AST) para uma pistola ou (AST + VIG) para um machado de guerra).', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('LAMPEJO DE SABER', 'Quando tira 13 ou mais em um teste para investigar uma criatura, item ou local — inclusive na ação Estudo —, você pode fazer até (NP) perguntas ao mestre sobre o tópico de sua investigação. Estas perguntas podem ser feitas imediatamente ou em um momento oportuno no futuro. O mestre deve responder com informações verdadeiras, mas você deve descrever o processo dedutivo de seu personagem. Este poder só pode ser usado uma vez na mesma criatura, item ou local.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('MEMÓRIA TREINADA', 'Você pode lembrar com perfeição dos detalhes de qualquer cena em que tenha estado na última semana. Você pode “voltar no tempo” dentro de sua mente para examinar ou investigar essas cenas de novo — seu poder Lampejo de Saber também pode ser usado nestas memórias.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ESPIRITUALISMO RITUALISTA', 'Você pode fazer rituais da disciplina espiritualismo. Rituais de espiritualismo usam (AST + VON) no teste de Magia.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('MAGIA DE SUPORTE', 'Quando lança um feitiço que tenha como alvo um ou mais aliados, se estiver com uma arma arcana equipada, escolha um destes aliados com quem você tenha um Laço. O aliado recebe um bônus igual à força do seu Laço com ele no próximo teste que fizer até o fim da cena.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('MAGIA ESPIRITUAL', 'Sempre que adquirir este poder, aprenda um feitiço de Espiritualista. Feitiços ofensivos de Espiritualista usam (AST + VON) no teste de Magia.', 'common', 0, 10, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('PODER CURATIVO', 'Quando lança um feitiço que tenha como alvo um ou mais aliados, se estiver com uma arma arcana equipada, cada aliado alvo recupera uma quantidade de PV igual a (3 + (NP × número de Laços que você tem)). Esta cura é separada de qualquer cura causada pelos efeitos do feitiço.', 'common', 0, 2, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('VISMAGUS', 'Quando lança um feitiço, caso não tenha PM para pagar seu custo total, em vez disso, você pode gastar uma quantidade de PV igual a (10 + o custo total em PM do feitiço). Se um feitiço lançado dessa forma faria você recuperar PV, você não o faz (outros alvos são afetados normalmente).', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ADRENALINA', 'Enquanto estiver em crise, você causa (NP × 2) pontos de dano adicional (seja através de ataques, feitiços, Arcanos, itens ou qualquer outro meio).', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ESPÍRITO INDOMÁVEL', 'Quando gasta um ou mais Pontos de Fabula, você recebe um benefício adicional — escolha um: você recupera (NP × 5) PV; ou você recupera (NP × 5) PM; ou você se recupera de uma única condição à sua escolha.', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('FRENESI', 'Seus testes de Precisão com adaga, luta, malho e armas de arremesso contam como um sucesso crítico se ambos os dados mostrarem um mesmo número, qualquer que seja (contanto que o teste não seja uma falha crítica).', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('PROVOCAR', 'Você pode usar uma ação e 5 PM para fazer um teste oposto de (VIG + VON) contra uma criatura que você possa ver — descreva de que maneira a provoca! Se passar, o alvo fica enfurecido e é compelido a se concentrar em você (ele deve fazer o possível para ter você como alvo de ataques e feitiços). A compulsão termina se você ficar inconsciente ou deixar a cena, ou se a criatura deixar de ficar enfurecida ou for provocada por outra pessoa. Você recebe um bônus igual a (NP) em testes de (VIG + VON) para este poder.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('RESISTIR', 'Quando faz a ação Guarda, se você escolher não dar cobertura a outra criatura, recupere uma quantidade de PV igual a (NP × a maior força de Laço que tiver) e escolha Vigor ou Vontade. Até o fim do seu próximo turno, o dado atual do Atributo escolhido é considerado um passo maior (máximo de d12).', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('DUPLO ESCUDEIRO', 'Você se torna capaz de equipar um escudo em seu espaço de mão dominante. Enquanto tiver dois escudos equipados, você recebe os benefícios de ambos os itens e pode tratá-los como a seguinte arma de luta de duas mãos: Escudos Gêmeos (VIG + VIG) (RA + 5) físico. Causa dano adicional igual ao seu (NP) em Maestria Defensiva.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('FORTALEZA', 'Aumente permanentemente seus PV máximos em (NP × 3).', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('GUARDA-COSTAS', 'Se você fizer a ação Guarda e escolher dar cobertura a um aliado, essa criatura torna-se Resistente a todos os tipos de dano até o início de seu próximo turno.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('MAESTRIA DEFENSIVA', 'Enquanto tiver um escudo ou uma armadura marcial equipada, todo o dano que você sofrer será reduzido em (NP) (aplicado antes de Afinidades a dano).', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('PROTEGER', 'Quando outra criatura é ameaçada por um ataque, feitiço ou outro perigo, você pode tomar o lugar dela. Quaisquer testes que forem parte do perigo serão realizados contra você; além disso, você pode declarar o uso deste poder antes ou depois da realização dos testes. Se o perigo já afetou você, ele o afetará duas vezes (resolva ambas as instâncias separadamente); além disso, você não pode proteger várias criaturas do mesmo perigo. Se usar este poder durante um conflito, você não poderá reutilizá-lo até o início de seu próximo turno.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('AGONIA', 'Uma vez por turno (inclusive os turnos de outras criaturas), após causar dano a uma ou mais inimigos com os quais tem um Laço, você recupera (NP × 2) Pontos de Vida e (NP × 2) Pontos de Mana.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('CORAÇÃO DA ESCURIDÃO', 'Uma vez por cena, quando entra em crise, escolha uma criatura específica que você possa ver e com a qual não tenha um Laço; você cria um Laço de ódio para com a criatura escolhida.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('GOLPE DAS SOMBRAS', 'Você aprendeu a canalizar sua força vital em seus ataques. Você pode usar uma ação para fazer um Golpe das Sombras: role seu dado atual de Vigor e perca uma quantidade de PV igual ao resultado. Se isto não reduzir seus PV a 0, você pode fazer um ataque livre com uma arma equipada; se atingir um ou mais alvos, você causa dano adicional igual a (NP + número rolado no dado de Vigor). Esse ataque causa dano de trevas e seu tipo não pode ser alterado.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('LIÇÃO DOLOROSA', 'Quando outra criatura faz você perder PV (com um ataque, feitiço ou qualquer outro método), você pode fazer a ação Estudo imediatamente, tendo-a como alvo. Se fizer isso, você faz o teste com um bônus igual a (NP). Lembre-se: você só pode estudar a mesma informação de uma criatura uma vez.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('SANGUE DAS TREVAS', 'Enquanto estiver em crise, você tem Resistência a dano de trevas e de veneno.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('CHUVA DE POÇÕES', 'Quando cria uma poção que restaura PV e/ou PM de uma única criatura, você pode fazer com que ela afete até (NP) criaturas adicionais. Se fizer isso, a poção restaura apenas metade da quantidade normal de PV e PM para cada criatura.', 'common', 0, 2, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ENGENHOCAS', 'Quando adquire este poder pela primeira vez, escolha um tipo de engenhoca: alquimia, infusões ou tecnomagia. Você recebe os benefícios básicos desse tipo de engenhoca. Sempre que adquirir este poder novamente, escolha uma opção: você recebe os benefícios básicos de um novo tipo de engenhoca; ou recebe os benefícios avançados de uma engenhoca cujos benefícios básicos já possua; ou recebe os benefícios superiores de uma engenhoca cujos benefícios avançados já possua.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('FÓRMULA SECRETA', 'Quando cria uma poção ou magisfera cujos efeitos restauram PV e/ou PM, cada recurso restaurado aumenta em (NP × 5). Quando cria um fragmento elemental, uma magisfera ou uma poção que cause dano, esse item causa (NP) pontos de dano adicional.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ITEM EMERGENCIAL', 'Uma vez por cena de conflito, quando estiver em crise, você pode fazer uma ação adicional no seu turno, mas deve ser a ação Inventário.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('VISIONÁRIO', 'Quando trabalha em um projeto, até (NP × 100) zênites do seu custo de material são pagos automaticamente. Além disso, você gera mais (NP) de progresso todos os dias. Se vários personagens com este poder trabalharem no mesmo projeto, os efeitos são cumulativos.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ALTA VELOCIDADE', 'No início de um conflito, você pode gastar 10 PM. Se fizer isso, escolha uma opção: faça um ataque livre com uma arma equipada; ou faça a ação Impedimento ou Objetivo. Isso acontece antes da primeira rodada. Você também recebe um bônus igual a (NP) em testes feitos como parte da opção escolhida.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ESQUIVA', 'Enquanto não tiver escudos ou armaduras marciais equipadas, sua Defesa aumenta em (NP).', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('GOLPE BAIXO', 'Quando atinge uma criatura com um ataque, caso essa criatura seja o único alvo do ataque e esteja sofrendo uma ou mais condições, você causa dano adicional igual a (NP + o número de condições afetando a criatura).', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ROUBO DE ALMA', 'Em um conflito, você pode usar uma ação para fazer um teste de (DES + VON) contra a Defesa Mágica de um inimigo que possa ver. Se o alvo for um soldado e você tiver sucesso, recupere (NP) PI; se ele for um elite ou um campeão, em vez disso você recebe o tesouro da alma do alvo: um item com valor em zênites igual ou inferior ao (nível do alvo multiplicado por 30 ou, se for um vilão, multiplicado por 50). Esse tesouro da alma aparece na sua mochila. Uma criatura pode ser furtada por este poder apenas uma vez. Você recebe um bônus igual a (NP) nos testes de (DES + VON) para este poder.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('VEJO VOCÊ MAIS TARDE', 'Você pode usar uma ação e 1 Ponto de Fabula para sumir da cena atual, reaparecendo quando quiser durante uma cena diferente em que outro PJ esteja. Descreva como você escapou e milagrosamente apareceu no novo local!', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('CHUVA DE LÂMINAS', 'Quando faz um ataque corpo a corpo, você pode gastar 10 PM para escolher uma opção: o ataque recebe multi (2); ou você aumenta em um a propriedade multi do ataque, até o máximo de multi (3).', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('CONTRA-ATAQUE', 'Quando um inimigo atinge ou erra um ataque corpo a corpo contra você, se o resultado do teste de Precisão for um número par, você pode fazer um ataque livre contra esse inimigo (depois que o ataque dele for resolvido). Esse ataque deve ser corpo a corpo e deve ter esse inimigo como único alvo; sua RA é considerada como 0 para calcular o dano causado por este ataque.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('QUEBRA-OSSOS', 'Quando atinge um ou mais alvos com um ataque corpo a corpo que fosse causar dano, você pode escolher não causar dano. Se fizer isso, escolha uma opção: deixar cada alvo atingido pelo ataque atordoado; ou deixar cada alvo atingido fraco; ou cada alvo atingido perde (NP × 10) PM. Descreva sua manobra!', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('MAESTRIA COM ARMAS CORPO A CORPO', 'Você recebe um bônus igual a (NP) em testes de Precisão corpo a corpo.', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('TRESPASSAR', 'Você pode usar uma ação e gastar 5 PM para fazer um ataque livre com uma arma corpo a corpo equipada. Este ataque deve ter somente uma criatura como alvo. Se acertar, você não causa dano e escolhe uma opção: destrua um escudo equipado pelo alvo; ou destrua a armadura equipada pelo alvo; ou todas as fontes causam (NP × 2) pontos de dano adicional ao alvo até o início do seu próximo turno.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ALIADO INESPERADO', 'Você pode usar uma ação e 1 Ponto de Fabula para escolher uma criatura que não seja hostil e seja capaz de ouvir e entender você. Se fizer isso, ela se torna solícita, desde que tratada com respeito e gentileza e você faça pedidos razoáveis.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('CONDENAR', 'Você pode usar uma ação e 5 PM para fazer um teste oposto de (AST + VON) contra um inimigo capaz de ouvir e entender suas acusações. Em um sucesso, o inimigo alvo perde (NP × 10) PM e você escolhe se ele fica abalado ou atordoado; além disso, todas as fontes causam (NP) pontos de dano adicional a esse inimigo até o início do seu próximo turno. Você recebe um bônus igual a (NP) em testes de (AST + VON) para este poder.', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('CONFIO EM VOCÊ', 'Quando outro PJ capaz de ouvir você fizer um teste, você pode gastar 1 Ponto de Fabula para convocar um dos Traços ou Laços dele, permitindo que ele role dados novamente ou melhore o resultado do teste (seguindo as regras normais). Em seguida, se você tem um Laço com o personagem alvo, ele recupera (NP × 10) PM.', 'common', 0, 2, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ENCORAJAR', 'Você pode usar uma ação e gastar 5 PM para escolher um aliado que possa ver e entender você. Esse aliado recupera (NP × 5) PV e escolhe Destreza, Vigor, Astúcia ou Vontade. Até o início do seu próximo turno, o dado atual do Atributo escolhido é considerado um passo maior (máximo de d12).', 'common', 0, 6, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('PERSUASIVO', 'Quando passar em um teste para preencher ou apagar as seções de um relógio, se a sua abordagem envolveu charme, diplomacia, enganação ou intimidação, você pode gastar até (NP × 20) PM. Se fizer isso, preencha ou apague uma seção adicional desse relógio para cada 20 PM gastos dessa maneira.', 'common', 0, 2, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('CONSUMIR', 'Quando causa dano a uma ou mais criaturas usando um feitiço, caso tenha uma adaga, arma arcana ou malho equipado, você recupera (NP × 2) PM.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('IMITAÇÃO MÁGICA', 'Quando vê um feitiço sendo lançado por uma criatura das espécies fera, monstro ou planta, você pode aprendê-lo como um de seus feitiços de Quimerista: se fizer isso, anote a espécie da criatura com a qual aprendeu. Na primeira vez que receber este poder, escolha (AST + VON) ou (VIG + VON). A partir de agora, seus feitiços ofensivos de Quimerista usam os Atributos escolhidos no teste de Magia, independentemente dos Atributos usados pela criatura com a qual você aprendeu o feitiço. Você pode memorizar até (NP + 2) feitiços de Quimerista diferentes desta maneira. Se quiser memorizar um novo feitiço de Quimerista, mas já tiver atingido o limite, você deve esquecer um dos antigos e substituí-lo pelo novo.', 'common', 0, 10, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('LÍNGUA DAS FERAS', 'Você pode se comunicar com criaturas das espécies fera, monstro e planta.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('PATOGÊNESE', 'Quando causa dano a uma ou mais criaturas com um de seus feitiços de Quimerista, alvos que sejam da mesma espécie da criatura com a qual você aprendeu o feitiço ficam envenenados.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('QUIMERISMO RITUALISTA', 'Você pode fazer rituais da disciplina quimerismo. Ao obter este poder, escolha (AST + VON) ou (VIG + VON). A partir de agora, seus rituais de quimerismo utilizam os Atributos escolhidos no teste de Magia.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ADVERSIDADE', 'Enquanto estiver sofrendo uma ou mais condições, você recebe +1 em todos os testes e causa 2 pontos de dano adicional (com Arcanos, ataques, feitiços, itens ou qualquer outro método) para cada condição que estiver sofrendo.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('AMBIDESTRIA', 'Você pode aplicar os benefícios de luta com duas armas a qualquer arma, mesmo às que pertencem a categorias diferentes ou que uma seja corpo a corpo e outra seja à distância (como adaga e arma de fogo). Enquanto você tiver duas armas equipadas e elas não compartilharem categorias, você recebe um bônus de +2 na Defesa e o segundo ataque que fizer em cada um dos seus turnos causa 5 pontos de dano adicional.', 'heroic', 1, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ATAQUE PODEROSO', 'Seus ataques corpo a corpo causam 5 pontos de dano adicional. Se estiver no 40° nível ou acima, esse dano aumenta para +10.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('BOLSOS FUNDOS', 'Você reduz custos de Pontos de Inventário em –1 (mínimo 1).', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('COMETA', 'Você aprende o feitiço supremo de entropista: Cometa. Cometa PM: 50. Alvo: especial. Duração: instantânea. Você abre um grande portal do Cosmos, convocando uma rocha astral do vazio. Escolha uma opção: você causa 60 pontos de dano a uma criatura que você possa ver; ou causa 40 pontos de dano a todos os inimigos que possa ver. Esses danos aumentam em +5 se você estiver no 20° nível ou acima, e em +10 se estiver no 40° nível ou acima. Esses danos não têm tipo (portanto, não são afetados por Afinidades a dano).', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('COMPANHEIRO HEROICO', 'Você recebe os seguintes benefícios: os PV máximos do companheiro aumentam em 10; seu companheiro causa 5 pontos de dano adicional; escolha um dos Atributos do companheiro: Destreza, Vigor, Astúcia ou Vontade. O dado básico do Atributo escolhido aumenta em um passo (máximo d12); o companheiro recebe um poder adicional. Quando você alcançar o 40º nível (ou se já o tiver ultrapassado), o companheiro recebe mais um poder. Converse com o mestre e os outros jogadores sobre suas decisões de poder.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('DESALMADO', 'Quando atinge uma criatura com um ataque, se apenas essa criatura for o alvo e você tiver um Laço com ela, pode gastar a metade de seus PV atuais (arredondada para baixo). Se fizer isso, o ataque causa (10 vezes a força de seu Laço com o alvo) pontos de dano adicional. Este poder só pode ser usado uma vez em cada um de seus turnos em um conflito.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('DOMÍNIO QUIMÉRICO', 'Escolha duas espécies entre construto, demônio, elemental e morto-vivo. Você pode usar seu poder Imitação Mágica para aprender feitiços de criaturas das espécies escolhidas. Este poder heroico pode ser adquirido até duas vezes, permitindo que você escolha duas das espécies mencionadas acima por vez. Sempre que adquirir este poder, você aumenta seu limite de feitiços memorizados de Quimerista em +2.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ECOS ARCANOS', 'Se os domínios de um ou mais Arcanos vinculados a você forem aplicáveis a um teste para apagar ou preencher uma ou mais seções de um relógio, ao obter sucesso no teste, você pode apagar ou preencher uma seção adicional desse relógio. O mestre tem a palavra final se um domínio é aplicável ou não.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ESPERANÇA', 'Você aprende o feitiço supremo de espiritualista: Esperança. Esperança PM: 40. Alvo: especial. Duração: instantânea. Você reacende as chamas da coragem e da esperança de um herói derrotado. Escolha um PJ que tenha se rendido e ainda esteja narrativamente presente na cena: esse alvo imediatamente recobra a consciência e recupera uma quantidade de PV igual à metade dos seus PV máximos. Observe que esse feitiço não cancela as consequências pela rendição do personagem e não tem utilidade se ele tiver saído de cena como parte da rendição. Um PJ só pode ser afetado por esse feitiço uma vez por cena; se o personagem voltar ao conflito por meio desse feitiço e depois for reduzido a 0 PV novamente, ele deve se sacrificar ou se render de acordo com as regras normais.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('FEITIÇO PODEROSO', 'Seus feitiços causam 5 pontos de dano adicional. Se estiver no 40° nível ou acima, esse dano aumenta para +10.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('FEITIÇOS EXTRAS', 'Quando adquirir este poder, aprenda dois feitiços de uma das seguintes listas: elementalista, entropista ou espiritualista. Ambos os feitiços devem ser da mesma lista e seguir as regras padrão da respectiva classe para serem lançados.', 'heroic', 1, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('GOLPE TEMPESTUOSO', 'Quando faz um ataque corpo a corpo com a propriedade multi, você recebe um bônus em seu teste de Precisão igual ao valor desta habilidade multi e o ataque causa 5 pontos de dano adicional. Se o ataque atingir uma única criatura, causa mais 5 pontos de dano.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('IMBATÍVEL', 'Uma vez por cena, quando estiver prestes a ficar com 0 PV, em vez disso você pode resistir à dor e ficar com exatamente 1 PV.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('IMUNIDADE À CONDIÇÃO', 'Você se torna Imune a uma única condição à sua escolha.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('MATEMÁGICA', 'Quando lança um feitiço com alvo “uma criatura”, escolha um Atributo (Destreza, Vigor, Astúcia ou Vontade) e um tipo de dado (d6, d8, d10 ou d12). Se o fizer, o alvo do feitiço se torna “todas as criaturas na cena cujo dado básico do Atributo escolhido corresponde à sua escolha” e seu custo total de PM é dobrado. Além disso, substitua todas as menções a “o alvo” no texto do feitiço por “cada alvo”; ou por “um ou mais alvos” se o feitiço for Anomalia, Dissipar, Espelhar ou Piedade. Quando o feitiço termina em um ou mais alvos, ele automaticamente termina em todos os alvos. Se lançar um feitiço ofensivo dessa forma, você faz um único teste de Magia e compara com a Defesa Mágica de cada alvo.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('MÃO DE GORILA', 'Você agora pode equipar armas de duas mãos das categorias espada, lança, malho e pesada usando um único espaço de mão. Além disso, o primeiro ataque que você fizer com uma arma de duas mãos em cada turno causa 5 pontos de dano adicional e ignora Resistências.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('MELHORIA', 'Em um descanso, você pode escolher qualquer número de armas, armaduras e/ou escudos entre aqueles em posse do seu grupo. Para cada item escolhido desta forma, você pode aplicar uma característica (se ele não tiver uma) ou substituir sua característica atual por uma diferente. Estas novas características devem estar nas listas de características disponíveis para itens do respectivo tipo e devem custar +1000 zênites ou menos. No fim do descanso, você deve gastar uma quantidade de zênites igual à soma de todos os custos, reduzida por (NP do seu poder Visionário, multiplicado por 100). Se o fizer, os itens são modificados conforme as suas escolhas.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('MIRA PERFEITA', 'Quando atinge uma ou mais criaturas com um ataque à distância e escolhe não causar dano para usar o poder Tiro de Aviso, você pode escolher duas opções em vez de uma; por exemplo, você poderia deixar cada criatura abalada e lenta ou infligir uma condição a cada criatura e reduzir os PM delas ao mesmo tempo.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('MURALHA', 'No início da primeira rodada de cada cena de conflito, você é Resistente a todos os tipos de dano e não pode sofrer condições (mas não se recupera de condições anteriores). Este benefício dura até o fim da primeira rodada.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('PILHAR', 'Quando usa Roubo de Alma, você pode escolher como alvo um número qualquer de criaturas ao mesmo tempo (faça um único teste e compare-o à Defesa Mágica de cada criatura que deseja furtar).', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('PI EXTRAS', 'Aumente permanentemente seus PI máximos em 4.', 'heroic', 1, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('PM EXTRAS', 'Aumente permanentemente seus PM máximos em 10. Se estiver no 40° nível ou acima, esses PM adicionais aumentam para 20.', 'heroic', 1, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('PREVISÍVEL!', 'Em um conflito, você pode usar uma ação e 20 PM para antecipar os próximos movimentos de uma criatura que você possa ver, desde que conheça dois ou mais Traços dela. Se o fizer, escolha um tipo de ação entre Ataque, Feitiço, Guarda, Objetivo ou Poder. Até o início do seu próximo turno, a criatura deve gastar 20 PM sempre que quiser fazer a ação escolhida. Se não puder, ela deve fazer uma ação diferente.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('PV EXTRAS', 'Aumente permanentemente seus PV máximos em 10. Se estiver no 40° nível ou acima, esses PV adicionais aumentam para 20.', 'heroic', 1, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('REPETIÇÃO', 'Uma vez por turno em um conflito, após usar o poder Condenar ou Encorajar, você pode reutilizá-lo (no mesmo alvo ou em outro). Você ainda deve pagar o custo em PM por esse segundo uso do poder.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('REVELAÇÃO', 'Você faz contato com um Arcano desconhecido, vinculando-o à sua alma. Esse Arcano deve ser criado em conjunto com o grupo; enquanto você viver, ninguém mais no seu mundo pode se vincular ao Arcano criado. Uma vez por cena, enquanto estiver fundido a um Arcano, você pode usar uma ação e gastar 2 Pontos de Fabula para acionar o efeito de dispensa desse Arcano (se houver) sem dispensá-lo — isso não ativa o poder Círculo Arcano.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('RETÓRICA DESARMANTE', 'Durante uma cena de conflito, você pode usar uma ação para escolher uma criatura de patente soldado que possa ouvir e entender você. Se essa criatura estiver abalada ou em crise, você pode gastar uma quantidade de PM igual a (20 + metade do nível da criatura alvo) para fazer com que ela saia do conflito de maneira pacífica. Descreva como você a convence a desistir de lutar.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('SUMIR', 'Quando atinge uma ou mais criaturas com um ataque, você pode gastar 1 Ponto de Fabula. Se fizer isso, cada uma dessas criaturas torna-se incapaz de ver você até o início do seu próximo turno.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('TIRO PODEROSO', 'Seus ataques à distância causam 5 pontos de dano adicional. Se estiver no 40° nível ou acima, esse dano aumenta para +10.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('VULCÃO', 'Você aprende o feitiço supremo de elementalista: Vulcão (se combinar melhor com seu personagem, você pode mudar o nome deste feitiço e trocar o tipo de dano causado por ar, gelo, raio ou terra). Vulcão PM: 40. Alvo: especial. Duração: instantânea. Você canaliza a fúria do planeta em uma poderosa onda de fogo e magma. Escolha uma opção: você causa 50 pontos de dano de fogo a uma criatura que você possa ver; ou causa 30 pontos de dano de fogo a todos os inimigos que possa ver. Se estiver no 20° nível ou acima, esse dano aumenta em 5; se estiver no 40° nível ou acima, aumenta em 10. Dano causado por este feitiço ignora Resistências e Imunidades.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ARSENAL VERMELHO', 'Você pode usar uma ação e gastar 5 PV para cobrir uma arma corpo a corpo equipada com uma camada do seu próprio sangue até o fim da cena. Se fizer isso, a arma passa a disparar cortes de sangue em alta velocidade, atingindo alvos que não podem ser acertados por ataques corpo a corpo. Um alvo que esteja voando e seja atingido por um ataque desta arma é imediatamente forçado a pousar.
Quando está em crise, você não gasta PV ao usar este poder e pode fazer um ataque livre como parte da mesma ação que usou para fazer isso.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('DOBRAR SANGUE', 'Você pode usar uma ação e gastar 20 PM para escolher um ataque básico ou feitiço conhecido de um inimigo que você possa ver. Então faça um teste
oposto contra ele de (VON + VIG). Se você vencer, o alvo é obrigado a usar a ação escolhida no próximo turno dele contra um alvo à sua escolha.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ESCUDO ESCARLATE', 'Enquanto estiver em crise, sua Defesa e Defesa mágica aumentam em (NP).', 'common', 0, 2, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('FRENESI SANGUINOLENTO', 'Quando rola um sucesso crítico ao fazer um ataque corpo a corpo, você pode gastar a oportunidade gerada para recuperar (NP × 10) PV.', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('HEMOFAGIA', 'Uma vez por rodada, quando outra criatura faz você perder PV, você pode gastar 10 PV para fazer um ataque livre contra essa criatura (depois que a ação dela for resolvida). Se acertar, não causa o dano da arma; em vez disso causa (NP + RA do teste de Precisão) de dano físico.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('INSTINTO ASSASSINO', 'Quando acerta uma criatura em crise com um ataque corpo a corpo, esse ataque causa 10 pontos de dano adicional. Se estiver no 40º nível ou acima, esse dano adicional aumenta para 20.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('GARFO E FACA', 'Quando usa Culinária para fazer um ataque livre, se você combinou apenas um 2 ingredientes, você também pode fazer o ataque causar dano normalmente. Se fizer isso, sua RA é considerada como 0 ao calcular o dano causado por este ataque.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('COZINHEIRO VIAJANTE', 'Após cada rolagem de viagem, se tiver o poder Culinária, você recebe (NP ×2) ingredientes.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('CULINÁRIA', 'Ao descansar em um assentamento, você recebe (NP) ingredientes.
Você pode usar uma ação e combinar 2 ou 3 ingredientes para preparar uma iguaria (veja a próxima página) e escolher um: aplicar os efeitos em você e num aliado que você possa ver; ou fazer um ataque livre com uma arma equipada. Esse ataque não causa dano, mas você aplica os efeitos da iguaria a cada inimigo atingido pelo ataque.
Você pode carregar consigo até 10 + (NP × 5) ingredientes e eles nunca estragam até que você os use. Se adquirir este poder na criação de personagem, você pode começar o jogo com dez ingredientes com sabores aleatórios.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('FEITO COM AMOR', 'Quando usa Culinária e aplica os efeitos da iguaria em você ou num aliado que você possa ver, você pode gastar até (NP × 10) PM. Para cada 10 PM gastos dessa forma, aplique os efeitos da iguaria num aliado adicional que você possa ver.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('SAL E PIMENTA', 'Ao preparar uma iguaria, você pode gastar 2 Pontos de Inventário. Se o fizer, mude o sabor de um ingrediente para outro sabor à sua escolha.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('ESPECIALIDADE DA CASA', 'Ao adquirir esse poder heroico, escolha três sabores diferentes entre amargo, salgado, azedo, doce e umami. Então, escolha três efeitos diferentes entre:
* Você causa 20 pontos de dano de (escolha um: luz, trevas) a todos os alvos desta iguaria. Se estiver no 30º nível ou acima, essa quantidade aumenta para 30. Escolha o tipo do efeito ao adquirir este poder.
* Durante o próximo turno de cada um dos alvos desta iguaria, todo o dano que eles causam torna-se de (escolha um: luz, trevas) e esse tipo não pode ser mudado. Escolha o tipo do efeito ao adquirir este poder.
* Cada alvo desta iguaria que estiver sob efeito de um ou mais feitiços com duração “Cena” deixa de estar sob o efeito desses feitiços.
* Escolha você mesmo ou um aliado que você possa ver. Da próxima vez que cada alvo desta iguaria fizer um ataque ou lançar um feitiço ofensivo (O) antes do fim desta cena, a criatura que você escolheu deve ser incluída entre os alvos do ataque ou feitiço, se possível.
* Cada alvo desta iguaria fica furioso.
* Cada alvo desta iguaria fica envenenado.
* Cada alvo desta iguaria recupera 30 PV e 30 PM. Se você estiver no 40º nível ou acima, o alvo recupera 40 PV e 40 PM em vez disso.
* Cada alvo desta iguaria se recupera de uma condição à sua escolha.
* Cada alvo desta iguaria se recupera das condições atordoado, furioso e abalado.
* Cada alvo desta iguaria se recupera das condições envenenado, lento e fraco. 
Quando criar uma iguaria usando exatamente 3 ingredientes em um conflito, se cada ingrediente for equivalente a um sabor diferente entre os escolhidos ao adquirir esse poder heroico, você pode ignorar todos os efeitos normais dessa iguaria. Se o fizer, você pode, em vez disso, aplicar um, dois ou todos os efeitos que você escolheu ao adquirir este poder heroico.', 'heroic', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Árvore da Vida', 'Ao remover uma magissemente de seu jardim, você pode escolher uma criatura que você possa ver. Se o alvo estiver em crise, ele recupera (5 + (NP × 5)) PV.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Cloromancia', 'Sempre que adquirir este poder, você conhece um tipo diferente de magissemente. Durante um conflito, se não houver magissementes em seu jardim, você pode usar uma ação e gastar 20 PM para plantar uma magissemente de um tipo que conheça.', 'common', 0, 10, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Enxerto', 'Enquanto houver uma magissemente em seu jardim e 1 ou mais seções de seu relógio de germinação estiverem preenchidas, você pode usar uma ação para remover essa magissemente de seu jardim. Se fizer isso, plante uma magissemente diferente, desde que seja uma das que você conhece. Isso não altera as seções preenchidas de seu relógio de germinação.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Influência Verdejante', 'Você pode fazer rituais da disciplina ritualismo. Além disso, pode usar ritualismo para criar, animar e/ou controlar vegetação, pólen, esporos e toxinas, mas não pode criar nem controlar NPCs da espécie planta dessa forma.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Jardinagem Marcial', 'Após plantar uma magissemente usando Cloromancia, mas não Enxerto, você pode escolher um: fazer um ataque livre com uma arma equipada; ou fazer a ação Feitiço sem usar uma ação, lançando um feitiço com custo total de PM igual ou inferior a (5 + (NP × 5)). Você ainda precisa pagar o custo em PM. Sua RA no teste de Precisão ou de Magia é considerada como 0 para calcular o dano causado por este ataque ou magia.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Cozinheiro Viajante', 'Após cada rolagem de viagem, se tiver o poder Culinária, você recebe (NP × 2) ingredientes.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Culinária', 'Ao descansar em um assentamento, você recebe (NP) ingredientes. Você pode usar uma ação e combinar 2 ou 3 ingredientes para preparar uma iguaria e escolher um: aplicar os efeitos em você e em um aliado que você possa ver; ou fazer um ataque livre com uma arma equipada. Esse ataque não causa dano, mas você aplica os efeitos da iguaria a cada inimigo atingido pelo ataque. Você pode carregar consigo até 10 + (NP × 5) ingredientes e eles nunca estragam até que você os use. Se adquirir este poder na criação de personagem, você pode começar o jogo com dez ingredientes com sabores aleatórios.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Feito com Amor', 'Quando usa Culinária e aplica os efeitos da iguaria em você ou num aliado que você possa ver, você pode gastar até (NP × 10) PM. Para cada 10 PM gastos dessa forma, aplique os efeitos da iguaria num aliado adicional que você possa ver.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Garfo e Faca', 'Quando usa Culinária para fazer um ataque livre, se você combinou apenas 2 ingredientes, você também pode fazer o ataque causar dano normalmente. Se fizer isso, sua RA é considerada como 0 ao calcular o dano causado por este ataque.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Sal e Pimenta', 'Ao preparar uma iguaria, você pode gastar 2 Pontos de Inventário. Se fizer isso, mude o sabor de um ingrediente para outro sabor à sua escolha.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Cascata', 'Após um inimigo que você possa ver perder PV graças ao dano causado por um de seus aliados, se o aliado causou dano adicional graças a uma de suas invocações do tipo Praga, você pode fazer um ataque livre com uma arma equipada. Esse ataque pode ter apenas o mesmo inimigo como alvo e você recebe um bônus no teste de Precisão igual a (NP). Se o atingir, todo dano causado pelo seu ataque é do mesmo tipo causado pelo aliado, e todas as invocações do tipo Praga que estão no alvo se dissipam após o ataque ser resolvido. Se dois ou mais inimigos engatilharem esse poder ao mesmo tempo, você pode fazer um ataque livre contra cada um deles, na ordem que preferir.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Expandir Manancial', 'Enquanto você estiver equipado com um arco, arma arcana, arma arremessável, arma de luta, espada ou mangual, suas invocações do tipo Explosão causam (NP) pontos de dano adicional e o dano adicional concedido por suas invocações do tipo Praga aumenta em (NP).', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Harmonia Elemental', 'Você consegue se comunicar verbalmente com criaturas elementais. Ao restaurar os PV de uma criatura com uma invocação ou feitiço, se houver um elemental presente na cena, o efeito restaura (NP × 5) PV adicionais.', 'common', 0, 2, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Invocação', 'Você pode usar uma ação e gastar 5 PM para fazer uma invocação acessando a energia de um dos mananciais presentes na cena. Seu (NP) determina a quais invocações você tem acesso.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Invocações Conectadas', 'Ao fazer uma invocação, você pode gastar até (NP × 10) PM adicionais. A cada 10 PM gastos desta forma, a invocação pode ter uma criatura adicional que você possa ver como alvo.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Data de Validade', 'Quando uma poção ou iguaria que você criou não causar dano, mas fizer uma ou mais criaturas recuperarem PV, você pode fazê-la, em vez de recuperar PV, causar dano de veneno igual a (metade do seu nível + (NP × 10)) a cada uma dessas criaturas. Esse tipo não pode mudar. Esse dano é dividido à metade se for causado a duas ou mais criaturas.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Estoque Pessoal', 'Quando você ou outro PJ for gastar (NP + 2) ou menos Pontos de Inventário, você pode gastar 1 Ponto de Comércio para o alvo ignorar esse custo.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Já Ouvi Falar', 'Quando você ou um aliado que puder ouvir e entender você fizer um teste para examinar uma criatura, item ou local, você pode gastar 1 Ponto de Comércio para conferir um bônus igual a (NP + 2) ao resultado do teste.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Ventos do Comércio', 'Após descansar numa área onde pode fazer comércio, você recebe (NP + 1) Pontos de Comércio. Você nunca pode ter mais que (NP + 3) Pontos de Comércio. Se adquirir este poder na criação de personagem, você começa o jogo com 2 Pontos de Comércio. Numa cena sem conflito, você pode gastar 2 Pontos de Comércio para escolher um: criar um item raro ou um material, aprovado pelo mestre, cujo valor em zênites seja igual ou inferior a (seu nível × 30z); ou criar um NPC que mora por perto, explicando seu ofício e como vocês se conheceram, para o mestre dizer o que ele deseja em troca de seus serviços.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Verdadeiro Tesouro', 'Uma vez por sessão, quando você ajudar um NPC ou uma comunidade a superar ganância e corrupção, melhorar a qualidade de vida ou coexistir com outras criaturas, se tiver Ventos do Comércio, você recebe (NP + 1) Pontos de Comércio.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Alma Quimérica', 'Ao lançar um dos seus feitiços de quimerista, você recebe um benefício baseado na espécie da criatura a quem o feitiço originalmente pertencia. Escolha um: você torna-se Resistente aos dois tipos de dano associados a essa espécie; ou, quando causa dano de um dos tipos associados a essa espécie, você causa 5 pontos de dano adicional. O benefício escolhido dura até o fim da cena ou até você lançar um feitiço de quimerista novamente. Tipos associados: terra e veneno (construto), fogo e gelo (demônio), ar e raio (elemental), ar e gelo (fera), raio e fogo (monstro), trevas e veneno (morto-vivo), terra e luz (planta).', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Mutante e Quimerista
Ter o poder Imitação Mágica');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Caçador Silencioso', 'Ao usar Alta Velocidade para fazer um ataque livre com um arco, lança ou arma de arremesso, esse ataque causa dano adicional igual a (5 × seu NP em Alta Velocidade). Além disso, se atacar uma ou mais criaturas com um arco, lança ou arma de arremesso, essas criaturas não podem fazer ataques livres até o fim do turno atual.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Atirador, Ladino e Mestre de Armas
Ter o poder Alta Velocidade');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Cloromancia Maior', 'Uma vez por turno, quando uma magissemente deixar seu jardim, se ela tiver um ou mais efeitos ativados no fim do seu turno, você pode gastar 20 PM. Se fizer isso, reproduza um desses efeitos, podendo escolher um efeito que não seja equivalente às seções atuais de seu relógio de germinação. Além disso, se tiver Influência Verdejante, seus rituais agora também podem influenciar e controlar criaturas de patente soldado da espécie planta, mas você ainda não é capaz de criá-las.', 'heroic', 0, 1, 'Dominar a classe Floralista');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Cochilo Poderoso', 'Em seu turno durante um conflito, você pode usar uma ação para recuperar um número de PV e PM igual a (20 + metade do seu nível) e se recuperar de todas as condições. Se fizer isso, seu turno termina imediatamente, você perde a capacidade de ver e ouvir, e sua Defesa e Defesa Mágica tornam-se iguais a 5 e não podem ser modificadas de nenhuma maneira. Essas penalidades duram até o início do seu próximo turno, até depois que você perder PV ou até depois que você for atingido por um ataque ou feitiço ofensivo.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Andarilho, Guardião e Mercador');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Conjuração Maromba', 'Ao fazer um teste de Magia para um feitiço ou ritual, você pode substituir um dos atributos por Vigor. Se o teste de Precisão da arma que estiver equipando incluir Vigor, você pode considerá-la como arcana para poderes e efeitos com esse pré-requisito.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Andarilho, Esper, Furioso, Guerreiro Sombrio e Quimerista');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Dedo Verde', 'Quando preencher uma ou mais seções de seu relógio de germinação, você pode escolher um: preencher 1 seção adicional; ou preencher 1 seção a menos, mínimo de 0 seções preenchidas. Se fizer isso, você não pode usar esse efeito novamente até seu relógio de germinação ter se esvaziado por completo. Além disso, dano causado por suas magissementes ignora Resistências.', 'heroic', 0, 1, 'Dominar a classe Floralista');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Dosagem Precisa', 'Poções e iguarias que você criar, assim como os feitiços que você lançar, agora podem fazer com que as criaturas recuperem PV e PM além dos seus PV e PM máximos. Não é possível que o PV ou PM atual de uma criatura seja maior que 150% de seus respectivos pontos máximos. No fim de cada cena, se a quantidade de PV e/ou PM de uma criatura ainda estiver acima do máximo, a pontuação se iguala à máxima.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Erudito, Gourmet, Inventor e Mercador');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Especialidade da Casa', 'Ao adquirir este poder heroico, escolha três sabores diferentes entre amargo, salgado, azedo, doce e umami. Então, escolha três efeitos diferentes da lista do poder. Quando criar uma iguaria usando exatamente 3 ingredientes em um conflito, se cada ingrediente for equivalente a um sabor diferente entre os escolhidos ao adquirir este poder, você pode ignorar todos os efeitos normais dessa iguaria. Se fizer isso, pode aplicar um, dois ou todos os efeitos escolhidos ao adquirir este poder heroico.', 'heroic', 0, 1, 'Dominar a classe Gourmet');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Golpe Valente', 'Quando usa Quebra-ossos, se seu ataque tiver apenas uma criatura como alvo e você tiver um escudo equipado, você pode desafiar essa criatura até o fim do seu próximo turno. Esse desafio também termina se a criatura for desafiada por outra pessoa ou se você desafiar outra criatura. Uma criatura desafiada deve incluir você entre os alvos dos seus ataques e feitiços ofensivos, se possível. Além disso, uma vez por turno, inclusive turnos de outras criaturas, quando você causar dano à criatura desafiada usando um ataque livre com uma arma corpo a corpo de uma mão ou com uma arma personalizada das categorias espada ou adaga, você pode causar 5 pontos de dano adicional a essa criatura.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Comandante, Furioso, Guardião, Mestre de Armas e Piloto');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Lado a Lado', 'Quando seu companheiro causar dano, ele causa 5 pontos de dano adicional. Quando seu companheiro fizer um teste, você pode gastar 1 Ponto de Fabula e evocar um dos Traços de seu companheiro para que ele role novamente um ou ambos os dados. Após usar Companheiro Fiel para seu companheiro fazer uma ação no seu turno, e depois que essa ação for resolvida, você pode escolher um: você e seu companheiro recuperam 10 PM cada; ou, na primeira vez em que você ou seu companheiro fizer um teste até o fim do seu próximo turno, esse teste recebe um bônus igual a (seu NP em Companheiro Fiel).', 'heroic', 0, 1, 'Dominar a classe Andarilho
Ter o poder Companheiro Fiel');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Levanta a Cabeça!', 'Ao usar Confio em Você em outro personagem, ele deve escolher entre Destreza, Astúcia, Vigor ou Vontade, então passa a considerar o dado atual do Atributo escolhido como se fosse um passo maior, máximo de d12. Esse benefício dura até o fim da cena ou até você usar Confio em Você nele outra vez.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Esper, Orador e Virtuoso
Ter o poder Confio em Você');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Luar Purificador', 'Quando atingir uma ou mais criaturas com um feitiço ofensivo, se tiver uma arma arcana equipada e a RA do seu teste de Magia for 8 ou mais, você pode fazer com que todas essas criaturas deixem de estar sob efeito de todos os feitiços com duração Cena que as estiverem afetando no momento. Ao lançar um feitiço que tenha um ou mais aliados como alvo, se tiver uma arma arcana equipada, você pode escolher uma condição entre abalado, atordoado, envenenado, fraco, furioso e lento. Se fizer isso, cada alvo se recupera da condição escolhida.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Entropista e Espiritualista');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Manancial Interior', 'Ao adquirir este poder heroico e sempre que você descansar, você pode escolher um manancial: água, ar, fogo, raio ou terra. Até o próximo descanso, você considera o manancial escolhido como disponível em todas as cenas, além dos mananciais já presentes; pode fazer rituais de elementalismo apenas se manipularem o elemento do manancial escolhido; torna-se Resistente ao tipo de dano do manancial escolhido; e, ao causar dano, pode mudar o tipo do dano causado para o mesmo do manancial escolhido, fazendo esse dano ignorar Resistências.', 'heroic', 0, 1, 'Dominar a classe Invocador');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Manipular Magia', 'Após um inimigo que você possa ver acertar ou errar seu personagem com um feitiço ofensivo, se o resultado do teste de Magia desse inimigo for um número par, você pode usar Invocação imediatamente e sem usar uma ação, após o feitiço ter sido resolvido, para fazer uma das suas invocações contra esse inimigo, sem gastar PM. Essa invocação não pode ser do tipo Praga e deve ter apenas esse inimigo como alvo. Você não pode usar Invocações Conectadas nesta ação.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Elementalista, Entropista, Invocador e Simbolista
Ter o poder Invocação');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Muralha de Espinhos', 'Você tem Resistência a dano de luz e de veneno. Após perder PV, se você estiver em crise e uma magissemente estiver em seu jardim, você pode preencher 1 seção do seu relógio de germinação. Além disso, ao usar Golpe das Sombras, você pode fazer o ataque deste poder causar dano de veneno em vez de dano de trevas. Esse tipo de dano ainda não pode ser mudado. Se fizer isso, seu Golpe das Sombras causa dano adicional igual a (2 × o número de seções preenchidas em seu relógio de germinação).', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Floralista e Guerreiro Sombrio
Ter o poder Cloromancia');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Palavras de Sabedoria', 'Ao fazer um teste de Apoio, se o líder do teste em Grupo puder ouvir e entender você, você pode usar (AST + AST), (AST + VON), ou (VON + VON) em vez dos atributos normalmente exigidos pelo teste de Apoio. Além disso, ao usar trabalho em equipe para ajudar o teste de outro personagem em seu turno durante uma cena de conflito, você pode gastar 10 PM. Se fizer isso, escolha até dois benefícios: o personagem alvo recupera 20 PM; o personagem alvo se recupera das condições atordoado, furioso e abalado; no fim do turno desse personagem, você faz um ataque livre com uma arma equipada ou faz a ação Feitiço sem custo de ação, lançando um feitiço cujo custo total em PM seja igual ou inferior a 20; ou, se esse personagem obtiver sucesso em seu teste e isso permitir que ele preencha ou apague uma ou mais seções de um relógio, ele pode preencher ou apagar uma seção adicional.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Comandante, Erudito e Orador');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Poder dos Cinco Mananciais', 'Após fazer uma invocação durante um conflito, você e até um aliado que você possa ver consideram um dos seus Atributos como um passo maior, máximo de d12. Isso dura até o fim da cena ou até você usar este poder outra vez. O atributo é definido pelo manancial invocado: ar (Astúcia), terra (um atributo à sua escolha), fogo (Destreza), raio (Vigor) ou água (Vontade).', 'heroic', 0, 1, 'Dominar a classe Invocador');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Por um Futuro Melhor', 'Quando gastar 1 ou mais Pontos de Fabula, se eles não forem gastos para alterar a história, você pode gastar a mesma quantidade em Pontos de Comércio em vez disso. Além disso, quando receber 2 ou mais Pontos de Comércio por meio de Verdadeiro Tesouro ou Ventos do Comércio, você pode escolher receber exatamente 1 Ponto de Comércio. Se fizer isso, escolha um assentamento a 1 dia de viagem de sua posição atual e aumente a prosperidade dele em uma quantidade igual a (seu NP em Ventos do Comércio + seu NP em Verdadeiro Tesouro). A prosperidade começa em 0 e não tem limite. A partir de 10, custos em zênites de você e aliados são reduzidos à metade na área; a partir de 15, vocês podem descansar livremente sem gastar zênites e testes de Viagem na área nunca usam dado maior que d8; a partir de 20, vilões precisam gastar o dobro de Pontos de Ultima nessa área.', 'heroic', 0, 1, 'Dominar a classe Mercador
Ter os poderes Ventos do Comércio e Verdadeiro Tesouro');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Refração Auramante', 'Escolha um tipo de dano entre ar, raio, terra, fogo, gelo e luz. Quando um inimigo que você possa ver causar dano em uma ou mais criaturas sob efeito de um feitiço Aura e/ou Barreira que você tenha lançado, o dano sofrido por cada uma dessas criaturas é reduzido em uma quantidade igual a (metade do seu nível de espiritualista) ou (seu nível ÷ 10), use o maior valor, e essa redução é aplicada antes de qualquer Afinidade. Em seguida, você pode causar uma quantidade de dano do tipo escolhido igual a (metade do seu nível) a esse inimigo. Se fizer isso, você não pode causar dano desta forma novamente até o início do seu próximo turno.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Arcanista e Espiritualista.
Ter o feitiço Aura e/ou Barreira');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Rodízio', 'Uma vez por cena, ao usar Culinária, você pode combinar quatro ingredientes em uma iguaria, ignorando o limite normal de três ingredientes. Fora isso, a iguaria segue a regra padrão.', 'heroic', 0, 1, 'Dominar a classe Gourmet');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Tranquilidade Efêmera', 'Quando lançar o feitiço Alucinação ou Torpor, você pode aplicar ambas as condições a cada alvo atingido pelo feitiço. Durante um conflito, você pode usar uma ação e gastar até 20 PM. A cada 10 PM gastos desta forma, você pode escolher um inimigo diferente que você possa ver e que esteja sofrendo duas ou mais condições. Cada inimigo escolhido se recupera de todas as condições e perde uma quantidade de PV igual a (metade do seu nível + (10 × o número de condições das quais o inimigo se recuperou dessa maneira)). Então, você recupera 20 PM para cada inimigo que entrou em Crise ou foi reduzido a 0 PV graças a esse efeito.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Dançarino, Esper, Espiritualista, Ladino e Simbolista');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Carga de Cavalaria', 'Em um conflito, você pode usar uma ação e gastar 10 PM para escolher um aliado que possa ouvi-lo. O aliado pode fazer imediatamente um ataque livre com uma arma equipada ou um ataque básico se for um NPC. Ele recebe um bônus no teste de Precisão igual ao seu NP, mas considera sua RA como 0 ao calcular o dano causado por este ataque.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Carruagem Devastadora', 'Após usar Decreto do Bispo, Carga de Cavalaria ou Roque do Rei, você pode escolher outro PJ que possa ouvi-lo e ainda não teve seu turno nesta rodada. O turno desse personagem acontece imediatamente após o seu nesta rodada.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Decreto do Bispo', 'Em um conflito, você pode usar uma ação e gastar 10 PM para escolher um: todos os custos em PM são dobrados; ou todas as fontes de dano causam (NP × 3) de dano adicional.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Gambito da Dama', 'Em um conflito, você pode usar uma ação para fazer um ataque livre com uma arma equipada, considerando sua RA como 0 ao calcular o dano. Após o ataque ser resolvido, escolha um: usar imediatamente Decreto do Bispo, Carga de Cavalaria ou Roque do Rei sem usar ação, pagando o custo apropriado de PM; ou um aliado que possa ouvir você recupera (5 + (NP × 5)) PV.', 'common', 0, 6, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Roque do Rei', 'Em um conflito, você pode usar uma ação e gastar 10 PM para escolher um: nenhuma criatura pode recuperar PV ou PM; ou todos os efeitos que restauram PM restauram (NP × 5) PM adicionais. O efeito escolhido dura até o início de seu próximo turno.', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Dança', 'Sempre que adquirir este poder, aprenda uma dança. Em seu turno numa cena de conflito, se não tiver uma armadura marcial equipada, você pode gastar 10 PM para apresentar uma dança que aprendeu. Isso não exige ação, mas só pode ser feito antes ou depois da sua ação e apenas uma vez por turno. Se apresentou uma dança diferente em seu turno anterior na mesma cena, o custo da nova dança é reduzido em 5 PM.', 'common', 0, 10, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Dançarino de Guerra', 'Após apresentar uma dança, seus ataques feitos com armas das categorias adaga, arremesso, luta e malho causam (NP) pontos de dano adicional até o início de seu próximo turno. Se tiver uma arma arcana equipada, feitiços ofensivos que você lançar também causam (NP) pontos de dano adicional até o início de seu próximo turno.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Me Acompanhe', 'Ao apresentar uma dança com duração até o início de seu próximo turno, você pode gastar 10 PM. Se fizer isso, escolha um personagem com quem você tem um Laço de afeto: o aliado também recebe os benefícios da dança como se fosse você, e tais benefícios duram até o início do seu próximo turno.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Sapateado Frenético', 'Ao apresentar uma dança com duração até o início de seu próximo turno, todos os testes opostos que dependam de acrobacia, coordenação ou velocidade recebem um bônus igual a (NP × 2) até o início de seu próximo turno.', 'common', 0, 2, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Troca de Figurino', 'Após apresentar uma dança, você pode fazer a ação Equipamento sem usar ações.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Conexão Simbólica', 'Você sempre sabe a direção exata de qualquer criatura que esteja com um de seus símbolos, desde que ela esteja a até 2 dias de viagem de sua posição.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Miragem', 'Você pode fazer rituais da disciplina ritualismo. Além disso, também pode usar ritualismo para criar ilusões visuais.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Simbolismo', 'Sempre que adquirir este poder, aprenda dois símbolos. Você pode ter até (NP + 1) símbolos ativos ao mesmo tempo; se criar mais símbolos além desse limite, antes deve escolher um de seus símbolos ativos para destruir. Você pode fazer a ação Inventário e gastar 2 PI para criar um símbolo que aprendeu e aplicá-lo em si mesmo, em um aliado que consiga ver ou, por meio de um ataque livre com uma arma equipada que não causa dano, aplicar uma cópia do símbolo a cada inimigo atingido.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Símbolos Mágicos', 'Se um aliado estiver com um de seus símbolos, ele pode fazer a ação Feitiço para destruir o símbolo e lançar um único feitiço entre aqueles que você conhece. O custo total em PM do feitiço deve ser igual ou menor a (NP × 10), e o aliado ainda deve pagar o custo de PM.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Toque Pessoal', 'Quando uma criatura que você possa ver e que esteja com um de seus símbolos sofrer dano ou recuperar PV e/ou PM, você pode fazer a criatura sofrer (NP) de dano adicional ou recuperar (NP) PV e/ou PM, respectivamente.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Barreira Sonora', 'Após cantar um verso em volume médio ou forte, qualquer quantidade de dano físico que você sofrer até o início de seu próximo turno é reduzido em (NP), antes de aplicar quaisquer Afinidades a dano.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Canto da Sereia', 'Você pode fazer rituais da disciplina ritualismo. Além disso, também pode usar ritualismo para criar ilusões sonoras.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Harmonia', 'Após afetar um ou mais inimigos com um verso, se tiver uma arma arcana equipada, você pode escolher um: até o início de seu próximo turno, seus aliados causam (NP) de dano adicional a esses inimigos; ou até o início de seu próximo turno, você recupera (NP) PM cada vez que esses inimigos sofrerem dano, recuperando (NP) PM para cada inimigo afetado quando a mesma fonte causar dano a dois ou mais deles ao mesmo tempo.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Magicanto', 'Em seu turno durante uma cena de conflito, você pode usar uma ação e gastar uma quantidade variável de PM para cantar um verso. Você só pode cantar um verso por turno, mesmo se puder fazer mais de uma ação. Ao adquirir este poder, você aprende todos os três volumes, além de uma escala e um tom. Sempre que adquiri-lo novamente, você pode aprender mais uma escala ou um tom.', 'common', 0, 10, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Vibrato', 'Após cantar um verso em volume fraco ou médio, você pode fazer um ataque livre com uma arma equipada, considerando sua RA como 0 ao calcular o dano.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Adepto das Lâminas', 'Enquanto tiver uma ou mais adagas corpo a corpo equipadas, sua Defesa e Defesa Mágica aumentam em +1 e você considera essas armas como das categorias arremesso, espada e luta para requisitos de poderes e outros efeitos. Além disso, seus ataques com adagas podem atingir criaturas que normalmente não podem ser alvos de ataques corpo a corpo.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Ladino e Mestre de Armas');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Batalha Incessante', 'O custo em PM de seus poderes Carga de Cavalaria, Decreto do Bispo e Roque do Rei é reduzido pela metade.', 'heroic', 0, 1, 'Dominar a classe Comandante');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Bimagus', 'Uma vez por turno em um conflito, se tiver uma arma arcana equipada, você pode usar uma ação e gastar de 20 a 50 PM para fazer a ação Feitiço duas vezes sem usar uma ação e sem gastar PM nos feitiços. O custo total em PM de ambas as magias deve ser 20 + a quantidade de PM gasta para usar este poder, e o segundo feitiço deve ter custo total em PM menor ou igual à metade do custo total do primeiro.', 'heroic', 0, 1, 'Dominar duas ou mais classes entre Elementalista, Entropista e Espiritualista.
Estar no 30° nível ou acima');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Corte Triplo', 'Desde que tenha uma espada ou adaga corpo a corpo e de uma mão equipada em cada espaço de mão convencional, você pode considerar seu espaço de armadura como um segundo espaço de mão secundária, usado apenas para equipar uma adaga ou espada corpo a corpo e de uma mão. Quando fizer a ação Ataque com adagas e/ou espadas equipadas, você pode atacar uma vez com cada arma, seguindo as regras de combate com duas armas: cada ataque perde multi e a RA de cada teste de Precisão é considerada 0 para calcular o dano.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Dançarino e Mestre de Armas');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Espetáculo', 'No início de seu turno em um conflito, se não tiver armadura marcial equipada, você pode gastar 1 Ponto de Fabula para apresentar até três danças diferentes que conheça, na ordem que preferir e sem custo em PM. Se fizer isso, você não pode apresentar danças até o fim do seu próximo turno.', 'heroic', 0, 1, 'Dominar a classe Dançarino');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Enxame Rodopiante', 'Quando faz um ataque à distância com uma arma de arremesso, se não tiver arma marcial ou escudo equipados, você recebe 1 Ponto de Ímpeto, até o máximo de 5. Seus ataques à distância com armas de arremesso causam dano adicional igual aos seus Pontos de Ímpeto atuais. Quando uma criatura acertar você com um ataque contra sua Defesa, você deve gastar todos os Pontos de Ímpeto e aumentar sua Defesa pelo mesmo valor, podendo transformar o acerto em falha. Você perde todos os Pontos de Ímpeto no fim de cada cena.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Atirador, Dançarino e Furioso');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Flecha Dupla', 'Quando faz um ataque à distância com um arco, se não tiver mais nenhuma arma equipada, você pode fazer dois ataques diferentes em vez de um, contra o mesmo alvo ou alvos diferentes. Ambos seguem as regras de combate com duas armas: cada ataque perde multi e a RA de cada teste de Precisão é considerada 0 para calcular o dano. Não é cumulativo com personalização rápida.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Atirador e Comandante');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Floresta de Ferro', 'Após acertar uma ou mais criaturas com um ataque corpo a corpo usando uma lança, se não tiver mais nenhuma arma equipada, você pode gastar 2 PM e escolher uma das criaturas atingidas. O ataque causa metade do dano a todos os alvos; então escolha Ataque, Guarda, Feitiço, Objetivo ou Poder. O alvo escolhido deve gastar 10 PM sempre que quiser fazer essa ação; se não tiver PM, deve fazer outro tipo de ação. O efeito dura até o início do seu próximo turno ou até você usar este poder novamente.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Comandante e Mestre de Armas');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Hoplita', 'Enquanto estiver com uma arma equipada no espaço de mão dominante e um escudo no espaço de mão secundária, seus ataques causam 5 pontos de dano adicional e sua Defesa aumenta em +1. Este poder não pode ser usado com armas personalizadas com aumento na Defesa nem com Duplo Escudeiro.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Comandante e Guardião');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Golpe Pulverizador', 'Após acertar uma criatura com Trespassar, se o ataque foi feito com uma arma pesada corpo a corpo, você pode causar dano igual à sua RA em vez de nenhum dano. Todas as fontes de dano adicional, inclusive a terceira opção de Trespassar, ainda se aplicam normalmente; ignore o dano causado pela arma.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Furioso, Guerreiro Sombrio e Mestre de Armas');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Guarda Mágica', 'Ao fazer a ação Guarda sem dar cobertura a outra criatura, até o início do seu próximo turno, quando uma criatura que você puder ver lançar um feitiço, após ela gastar os PM, você pode gastar PM igual a 10 + o custo total em PM do feitiço para interrompê-lo e negar seus efeitos. O feitiço não é lançado, mas o alvo ainda gasta a ação.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Elementalista, Entropista, Espiritualista e Quimerista');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Grande Invocação', 'Quando invocar um Arcano, você pode gastar 1 Ponto de Fabula e metade dos seus PV atuais para manifestá-lo como uma criatura de patente soldado da espécie demônio sob seu controle. Ela atua como aliada em seu próprio turno, tem nível igual ao seu, atributos, PV, resistências e benefícios de fusão definidos pelas regras do poder, além de ataque básico e efeitos de dispensar do Arcano. A criatura desaparece se for reduzida a 0 PV, se você morrer, ficar inconsciente, deixar a cena, invocar outro Arcano, fizer Grande Invocação de outro Arcano, no fim da cena ou sob suas ordens.', 'heroic', 0, 1, 'Dominar a classe Arcanista.
Estar no 30° nível ou acima');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Maré Crescente', 'Quando faz um ataque corpo a corpo com uma arma de luta, se não tiver mais nenhuma arma marcial ou escudo equipados, você recebe 1 Ponto de Coragem. Seus ataques corpo a corpo com armas de luta causam dano adicional igual a 2 + seus Pontos de Coragem atuais. No fim da cena ou se acumular 5 ou mais Pontos de Coragem no fim do seu turno, você gasta todos esses pontos e recupera 10 PV e PM.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Furioso e Mestre de Armas');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Mira Arcana', 'Quando atinge uma ou mais criaturas com um ataque usando uma arma arcana, o ataque causa 5 pontos de dano adicional e você pode escolher um dos alvos atingidos. Se o próximo feitiço ofensivo que você lançar nesta cena tiver apenas essa criatura como alvo, considere o teste de Magia desse feitiço como sucesso crítico se ambos os dados rolarem o mesmo número, desde que não seja falha crítica.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Atirador, Mestre de Armas e Simbolista');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Momento Fugaz', 'Quando fizer um Contra-ataque corpo a corpo com uma espada, você pode usar sua RA no dano causado pelo ataque, sem precisar considerá-la como 0.', 'heroic', 0, 1, 'Dominar a classe Mestre de Armas.
Ter o poder Contra-ataque');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Música Tema', 'Ao adquirir este poder, você recebe uma música-tema e escolhe uma escala que conhece. Uma vez por cena de conflito, após cantar um verso nessa escala, você pode iniciar sua música-tema. Enquanto ela durar, você torna-se Resistente ao tipo de dano da escala, causa 5 pontos de dano adicional ao causar dano desse tipo, e o custo em PM para cantar versos na mesma escala é reduzido pela metade para você e aliados que também possam cantar versos. A música termina no fim da cena, se você sair de cena, ficar inconsciente ou morrer, se alguém cantar um verso de escala diferente, se você não cantar verso até o fim do seu turno ou se outro personagem iniciar outra música-tema.', 'heroic', 0, 1, 'Dominar a classe Virtuoso');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Paso Doble', 'Enquanto estiver em crise, você ignora o custo em PM do poder Me Acompanhe.', 'heroic', 0, 1, 'Dominar a classe Dançarino.
Ter o poder Me Acompanhe');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Rituais Ágeis', 'Quando iniciar um ritual em uma cena de conflito, seu relógio de ritual é criado com duas seções a menos que o normal, mínimo de quatro seções.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Elementalista, Entropista, Espiritualista e Quimerista');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Selos Rituais', 'Quando faz um ritual fora de uma cena de conflito, se o ritual tiver custo total em PM igual ou menor que 60, você pode interromper o processo imediatamente antes do teste de Magia e armazenar os efeitos em um selo de ritual sobre uma superfície que possa tocar. Escolha um gatilho; quando ele for ativado, o selo desaparece e o ritual se conclui no local do selo, com teste de Magia e efeitos resolvidos normalmente. Você só pode ter um selo de ritual ativo por vez.', 'heroic', 0, 1, 'Dominar a classe Simbolista');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Tábula Rasa', 'Após usar Decreto do Bispo ou Roque do Rei, se estiver em crise, você pode fazer cada inimigo presente na cena perder 10 PV. Se estiver no 20° nível ou acima, esse dano aumenta para 20; se estiver no 40° nível ou acima, aumenta para 30.', 'heroic', 0, 1, 'Dominar a classe Comandante');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Teia de Aranha', 'Quando faz um ataque corpo a corpo com um malho, se não tiver mais nenhuma arma equipada, você pode fazer dois ataques separados em vez de um, contra o mesmo alvo ou alvos diferentes. Ambos seguem as regras de combate com duas armas: cada ataque perde multi e a RA de cada teste de Precisão é considerada 0 para calcular o dano. Não é cumulativo com personalização rápida.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Furioso e Mestre de Armas');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Tela em Branco', 'Você pode usar uma ação e gastar até 30 PM para escolher uma criatura que você possa ver para cada 5 PM gastos. Cada alvo escolhido se recupera de todas as condições e deixa de ser afetado por qualquer efeito com duração de Cena que o estivesse afetando.', 'heroic', 0, 1, 'Dominar a classe Simbolista');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Tiroteio', 'Após negar um ataque à distância usando Fogo Cruzado, se seu teste de Precisão for um número par, você pode fazer um ataque livre contra o atacante com uma arma de fogo à distância equipada. Este ataque deve ter o inimigo como único alvo e sua RA é considerada 0 para calcular o dano causado.', 'heroic', 0, 1, 'Dominar a classe Atirador');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Trilha Épica', 'Quando canta um verso de volume médio ou forte, você pode dobrar seu custo em PM ou gastar 1 Ponto de Fabula. Se fizer isso, testes de Precisão feitos por você e todos os aliados que puderem ouvi-lo são considerados sucesso crítico se ambos os dados rolarem o mesmo número, desde que não seja falha crítica.', 'heroic', 0, 1, 'Dominar a classe Virtuoso');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Dons Psíquicos', 'Sempre que adquirir este poder, você recebe um dom. Ao adquirir Dons Psíquicos, você também recebe um Relógio Mental com 4 seções, usado para determinar o custo e a efetividade dos dons.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Foco Cognitivo', 'No início do seu turno durante um conflito, você pode escolher um aliado que possa ouvir você ou um inimigo que você possa ver e esteja abalado, atordoado e/ou enfurecido. Até o início do próximo turno, esta criatura será seu foco. Você recebe bônus igual a (NP) em testes para examinar seu foco, em testes de Precisão e Magia de ataques e feitiços ofensivos que tenham seu foco entre os alvos. Quando você faz seu foco recuperar PV e/ou PM, ele recupera (NP × 2) PV e/ou PM adicionais.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Hipercognição', 'O custo total em PM de seus feitiços e versos que têm seu foco entre os alvos é reduzido em (NP); ou em (NP × 2) se seu foco for o único alvo, até o mínimo de 0 PM.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Navegador', 'Você pode se comunicar telepaticamente com qualquer aliado consciente que esteja a 1 dia de viagem; para poderes e condições, vocês podem ouvir um ao outro. Você pode fazer rituais da disciplina ritualismo. Além disso, pode usar ritualismo para transportar criaturas para dentro e fora da rede de almas, reunir informações e rastrear entidades enquanto estiverem na rede.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Psicocinese', 'Quando faz um teste de Precisão, você pode substituir um dos dados de atributo por Vontade, como (DES + VON) para um arco curto. Além disso, seus ataques corpo a corpo com espadas ou armas arcanas podem atingir criaturas voadoras.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Acromorfose', 'Seus testes de Precisão para ataques desarmados recebem bônus igual ao seu (NP) e estes ataques causam (6 + (NP × 2)) pontos de dano adicional. No início do seu turno durante um conflito, você pode escolher uma categoria de arma que não seja luta; seus ataques desarmados passam a pertencer à categoria escolhida até o início do seu próximo turno. Se escolher arco, arma de fogo ou arremesso, eles se tornam armas à distância; se escolher adaga ou espada, eles não podem ser usados com Corte Triplo.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Biofagia', 'Se estiver em crise, você pode recuperar (NP × 5) PV depois que um dos seus ataques ou feitiços ofensivos fizer um ou mais inimigos perderem PV.', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Ecdise', 'Após perder PV ao sofrer dano, se esse dano for de um tipo que não seja físico, você pode gastar 10 PV para receber Resistência ao tipo do dano sofrido até que use este poder novamente.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Genoclepse', 'Quando causar dano a um ou mais NPCs, você pode descobrir sua espécie. Além disso, o mestre deve escolher (NP) terioformas que reflitam esses NPCs; se você tiver Teriomorfose, pode pagar imediatamente o custo em PV desse poder para usá-lo ao manifestar essas terioformas, mesmo que não estejam entre as que você aprendeu.', 'common', 0, 2, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Teriomorfose', 'Sempre que adquirir este poder, você aprende uma terioforma. Você pode usar uma ação e gastar um terço dos seus PV atuais, arredondados para baixo, para manifestar os efeitos de até duas terioformas dentre as que aprendeu.', 'common', 0, 6, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Compressão Tecnológica', 'Quando não tiver ninguém a bordo do seu veículo pessoal, você pode fazê-lo desaparecer do mundo de jogo a qualquer momento. Se seu veículo pessoal não estiver presente no mundo de jogo e você estiver em um espaço grande o bastante para ele, pode usar a ação Inventário e gastar 2 PI para fazê-lo aparecer perto de você, e pode embarcar sem custos.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Configuração Flexível', 'Ao usar a ação Equipamento ou Guarda enquanto estiver pilotando seu veículo pessoal, você pode escolher até (NP) dos seus módulos ativos e desativá-los. Se fizer isso, escolha uma quantidade de até (NP) de módulos inativos e os ative.', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Coração no Motor', 'No início do seu turno durante um conflito, se estiver pilotando seu veículo pessoal, você pode gastar 10 PM. Se fizer isso, escolha um: na próxima vez que causar dano nesse turno, cause (NP × 2) pontos de dano adicional; na próxima vez que sofrer dano antes do início do seu próximo turno, reduza esse dano em (NP × 2), antes de aplicar Afinidades; ou recupere-se da condição lento ou fraco.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Pulso Firme', 'Ao fazer um teste de Precisão com um módulo de arma, você pode substituir um de seus atributos por Vigor, como (VIG + VON) para um módulo arcano.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Veículo Pessoal', 'Ao adquirir este poder, você recebe um veículo pessoal com uma estrutura à sua escolha e três módulos diferentes à sua escolha. Sempre que adquirir este poder novamente, você adquire dois módulos adicionais à sua escolha.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Acromorfose Maior', 'Você recebe benefícios com base na categoria atual dos seus ataques desarmados: adaga, arcana, arremesso ou luta consideram a Defesa de cada alvo como igual ao dado de Astúcia atual do alvo; arco ou espada causam 5 pontos de dano adicional quando têm duas ou mais criaturas como alvo; arma de fogo ou pesada causam 5 pontos de dano adicional a construtos e a criaturas não construtos com escudo e/ou armadura marcial; lança ou malho aumentam sua Defesa em +2 e permitem que ataques desarmados atinjam criaturas voadoras. Se seus ataques desarmados forem considerados em mais de uma categoria, você recebe todos os benefícios correspondentes.', 'heroic', 0, 1, 'Dominar a classe Mutante.
Ter o poder Acromorfose');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Bruxa de Aço', 'Após lançar o primeiro feitiço do seu turno em um conflito, se estiver pilotando seu veículo pessoal, você pode escolher um após resolver o feitiço: desativar um módulo ativo e ativar um módulo inativo; fazer com que o próximo feitiço que causar dano antes do fim da cena cause 5 pontos de dano adicional; ou fazer com que o próximo feitiço que restaurar PV antes do fim da cena restaure 10 PV adicionais de cada alvo.', 'heroic', 0, 1, 'Dominar a classe Piloto');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Câmera Lenta', 'Você recebe bônus no modificador de iniciativa igual a (seu NP em Esquiva + seu NP em Tempo Roubado). Se não tiver escudo ou armadura marcial equipados, todo dano que você sofre é reduzido em quantidade igual ao seu NP em Esquiva, antes de Afinidades, e você causa dano adicional igual ao seu NP em Tempo Roubado.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Entropista e Ladino.
Ter o poder Esquiva e/ou Tempo Roubado');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Campo Psíquico', 'Seus dons com o evento “Quando você causa dano” também podem ser usados quando um aliado que consegue ouvir você causa dano. Se tiver Escudo Psíquico, ele passa a permitir que você e todos os aliados que possam ouvir você considerem Defesa e Defesa Mágica iguais a (seu dado de Vontade atual + (2 × seções preenchidas em seu Relógio Mental)) para o teste, se esse valor for melhor.', 'heroic', 0, 1, 'Dominar a classe Esper');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Descarga de Ondas Mentais', 'Enquanto seu Relógio Mental estiver preenchido, você pode usar uma ação para apagar todas as suas seções. Se fizer isso, escolha um: causar 20 pontos de dano físico a todos os inimigos presentes na cena; ou causar 30 pontos de dano físico a um único inimigo que você possa ver. Se estiver no 20° nível ou acima, esse valor aumenta em 10; se estiver no 40° nível ou acima, aumenta em 20.', 'heroic', 0, 1, 'Dominar a classe Esper');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Ecdise Maior', 'Ao usar Ecdise, você pode escolher uma ou ambas as opções: recuperar-se de todas as condições; e/ou deixar de ser afetado por todos os feitiços com duração de Cena que estejam afetando você.', 'heroic', 0, 1, 'Dominar a classe Mutante');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Isca Chamariz', 'Ao usar Olhos de Águia e escolher a primeira opção, se não houver uma isca chamariz na cena, você pode gastar 10 PM para criá-la com PV iguais a (metade do seu nível + (5 × seu NP em Olhos de Águia)). Quando um inimigo que possa vê-la causar dano a uma ou mais criaturas, a isca sofre dano no lugar de uma dessas criaturas, escolhida aleatoriamente. Quando um inimigo reduz sua isca a 0 PV, ela é destruída e você rola 1d10; se o resultado for igual ou menor que (3 + seu NP em Olhos de Águia), você pode fazer um ataque livre com arma de fogo ou arco equipado contra esse inimigo, com bônus igual ao seu NP em Olhos de Águia e dano que ignora Imunidades e Resistências. A isca não pode recuperar PV e é destruída no fim da cena.', 'heroic', 0, 1, 'Dominar a classe Atirador.
Ter o poder Olhos de Águia');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Magicanhão Quântico', 'Seus ataques com o magicanhão causam 5 pontos de dano adicional. Ao fazer a ação Ataque com seu magicanhão, se não tiver outra arma equipada, você pode escolher um: destruir o magicanhão e imediatamente criar e equipar um novo sem custo, usando-o no ataque; fazer o ataque ganhar multi (3); ou fazer dois ataques separados em vez de um, seguindo as regras de ataque com duas armas.', 'heroic', 0, 1, 'Dominar a classe Inventor.
Ter o benefício tecnomagia: avançada do poder Engenhocas');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Mimeoclepse', 'Ao usar Genoclepse em um NPC cuja espécie esteja entre aquelas das quais você consegue aprender feitiços com Imitação Mágica, o mestre deve revelar todos os feitiços conhecidos por esse NPC. Se o NPC conhecer um ou mais feitiços, você pode aprender um deles como um de seus feitiços de quimerista.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Mutante e Quimerista.
Ter os poderes Genoclepse e Imitação Mágica');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Nebulização', 'Ao criar uma poção, você recebe 1 Ponto de Nebulização, ou 2 se a poção foi criada pela alquimia do poder Engenhocas. Poções e fragmentos elementais criados por você causam dano adicional igual ao dobro dos seus Pontos de Nebulização atuais. Poções criadas por você que recuperem PV e/ou PM restauram PV e/ou PM adicionais equivalentes a (5 × seus Pontos de Nebulização atuais). Você nunca pode ter mais que 5 Pontos de Nebulização e perde todos no fim de cada cena.', 'heroic', 0, 1, 'Dominar a classe Inventor.
Ter o benefício alquimia: avançada do poder Engenhocas');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Ou Vai ou Racha', 'Ao atacar com uma arma, você pode declarar “ou vai ou racha” antes do teste de Precisão. Se fizer isso, a RA do teste é dobrada para determinar o dano e você aplica penalidades se o resultado for par: se a arma for mutável, ela muda de forma e não pode mudar novamente até o fim da cena; se não for mutável ou não puder mudar de forma, ela é posta na mochila e não pode ser equipada até o fim da cena, mas você pode fazer a ação Equipamento imediatamente sem custo. Não se aplica a ataques desarmados, armas improvisadas, módulos de arma ou escudos gêmeos.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Furioso e Guerreiro Sombrio');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Pisar no Calo', 'Quando tiver sucesso ao usar Condenar contra um inimigo com pelo menos um Traço que você conheça, você recupera PM igual à metade dos PM perdidos pelo alvo e faz com que ele fique enfurecido, em vez das condições normais. Além disso, ao fazer um teste oposto contra uma criatura enfurecida, ou teste de Precisão ou Magia para ataque ou feitiço ofensivo que tenha uma ou mais criaturas enfurecidas entre os alvos, você tem sucesso crítico quando os dois dados mostram o mesmo número, se não for falha crítica.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Orador e Virtuoso.
Ter o poder Condenar');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Sincronização Dinâmica', 'No início do seu turno em um conflito, se estiver pilotando seu veículo pessoal, você pode sincronizar com outro PJ pilotando seu próprio veículo pessoal ou com outro PJ passageiro do seu veículo pessoal. Ambos recebem benefícios enquanto a sincronização estiver ativa: ao fazer um teste, pode usar dados atuais de atributos do outro personagem; ao causar dano, causa dano adicional igual à soma das forças dos Laços entre vocês; pode usar uma ação para fazer um ataque livre com módulo de arma ativo ou inativo no veículo pessoal do outro; e, após o fim do seu turno, se o outro PJ ainda não agiu na rodada, ele pode agir imediatamente. A sincronização dura até o fim da cena ou até uma das condições de encerramento ocorrer.', 'heroic', 0, 1, 'Dominar a classe Piloto');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Sobrecarga Explosiva', 'Escolha um tipo de dano entre fogo, gelo, luz, raio e trevas. Quando você for reduzido a 0 PV pela primeira vez durante uma cena, se estiver dirigindo seu veículo pessoal, pode ficar com exatamente 1 PV. Se fizer isso, você e passageiros deixam o veículo, que desaparece do mundo de jogo, e você causa dano igual ao seu valor de crise a uma única criatura que possa ver, do tipo escolhido. Se o veículo desaparecer assim, o próximo uso de Compressão Tecnológica custa 1 Ponto de Fabula adicional.', 'heroic', 0, 1, 'Dominar a classe Piloto.
Ter o poder Compressão Tecnológica');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Soldado Arcano', 'Você pode usar uma ação para fazer um ataque livre com uma arma equipada contra um único inimigo. Se acertar, sua RA é considerada 0 para calcular o dano. Depois de resolver o ataque, se acertou, você pode fazer a ação Feitiço sem custo de ação: o feitiço deve ser ofensivo, ter custo total em PM igual ou menor que 20 e ter como alvo apenas o inimigo atacado; você ainda paga os PM e faz o teste de Magia. A RA do teste de Magia é considerada 0 para calcular dano ou outros efeitos.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Atirador, Elementalista e Mestre de Armas.
Conhecer ao menos dois feitiços ofensivos');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Sonho Partido', 'Quando acertar uma ou mais criaturas com um ataque de Golpe das Sombras usando uma espada, cada uma perde PM igual ao número rolado no dado de Vigor para Golpe das Sombras. Então, se esse valor for 8 ou maior, você pode escolher uma criatura atingida. Se ela for seu foco ou você tiver um Laço com ela, ela fará uma ação a menos no próximo turno, mínimo de zero ações.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Esper e Guerreiro Sombrio');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Teriomorfose Maior', 'Ao usar Teriomorfose no seu turno em um conflito, se isso não acontecer através de Genoclepse, você pode manifestar os efeitos de até três terioformas dentre as que já aprendeu, em vez de apenas duas. Em seguida, pode fazer uma ação adicional. Esta ação não pode ser usada para Teriomorfose.', 'heroic', 0, 1, 'Dominar a classe Mutante');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Varredura Rápida', 'Ao fazer a ação Estudo em um conflito, você pode examinar as fichas de todos os inimigos que possa ver. Se fizer isso, faça um único teste aberto (AST + AST) e aplique o resultado separadamente a cada inimigo. Se tiver Lampejo de Saber, esse teste não pode ativá-lo.', 'heroic', 0, 1, 'Dominar a classe Erudito');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Constelação do Boitatá', 'Você pode usar uma ação e gastar 5 PM para fazer um teste de (AST + VON) contra a Def.M de um inimigo que você possa ver, causando (NP × 10) pontos de dano de fogo se o atingir. Se consumir uma carga celeste, uma criatura que você possa ver torna-se Resistente a fogo até o fim da cena. Você também gera (NP) cargas solares que duram até o fim da cena.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Constelação do Boto', 'Você pode usar uma ação e gastar 5 PM para alinhar os astros de um aliado que você possa ver. Até o fim da cena, o alvo pode trocar um atributo de um teste por AST ou VON. Se consumir uma carga solar, o alvo recebe +1 no teste. Você também gera (NP) cargas estelares que duram até o fim da cena.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Constelação do Cão Dourado', 'Você pode usar uma ação e gastar 10 PM para amaldiçoar um inimigo que você possa ver. Até o início do seu próximo turno, todas as fontes que causarem dano de luz ao alvo causam (NP) pontos de dano adicional. Se consumir uma carga estelar, todo dano de luz causado ao alvo ignora Imunidades e Resistências. Você também gera (NP) cargas meteóricas que duram até o fim da cena.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Constelação da Rasga-Mortalha', 'Você pode fazer rituais da disciplina ritualismo. Além disso, também pode usar ritualismo para consultar as estrelas sobre possíveis eventos futuros, obter conhecimento de lendas e até realizar pequenos desejos.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Constelação do Saci', 'Você pode usar uma ação e gastar 10 PM para acelerar um aliado que você possa ver. No próximo turno do alvo, ele pode fazer uma ação Equipamento, Guarda, Estudo ou Objetivo sem usar uma ação. Se consumir uma carga meteórica, ele também pode fazer um ataque livre, mas a RA do teste de Precisão desse ataque é considerada 0 para calcular o dano. Você também gera (NP) cargas celestes que duram até o fim da cena.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Cabra da Peste', 'Uma vez por cena, se estiver em crise, você pode usar uma ação e gastar 1 Ponto de Fabula para se recuperar de todas as condições e recuperar PV igual a (NP × 10). Se gastar 1 Ponto de Ultima em vez do Ponto de Fabula para usar este poder, também recupera PM igual a (NP × 10).', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Líder de Bando', 'Quando for o líder de um teste em grupo, e se um ou mais personagens apoiadores tiverem um Laço com você, some as duas forças mais altas dentre esses Laços, em vez de apenas a força mais alta.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Redistribuir Riquezas', 'No fim de uma cena de conflito na qual um vilão foi reduzido a 0 PV, você recebe (1d6 × NP) PI para distribuir entre os PJs. Além disso, se o vilão tiver mais do que 1 Ponto de Ultima no fim do conflito, você rouba 1 Ponto de Ultima dele e anota em sua ficha. Você só pode ter 1 Ponto de Ultima por vez.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Sertanejo', 'Você possui uma conexão com uma região de terras áridas e desafiadoras, afastada da costa e distante dos costumes da civilização. Ao adquirir este poder, descreva esse lugar e defina com o grupo o conceito de sertanejo no seu mundo de jogo. Essa região conta como uma segunda Origem para você. Se usar um Ponto de Fabula para evocá-la, você pode gastar 1 Ponto de Ultima em vez disso.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Valhacouto', 'No fim de um descanso, você pode gastar 1 Ponto de Fabula para seu bando trazer (NP + 1) Suprimentos, que duram até você usar este poder novamente. Quando faz um teste de Viagem, pode gastar 1 Suprimento para rolar o dado novamente. Além disso, pode gastar 1 Suprimento para criar uma barraca mágica. Se gastar 1 Ponto de Ultima ao usar este poder, o número de suprimentos aumenta em +2.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Altos e Baixos', 'Quando rola um sucesso crítico ou uma falha crítica, você pode comprar uma carta do seu baralho. Se fizer isso, descarte uma carta da sua mão.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Carta Armadilha', 'Após um inimigo que você possa ver fazer uma ação num conflito, você pode declarar um naipe do seu baralho após resolver a ação. Então ponha na pilha de descarte, com face para cima, a primeira carta do fundo do baralho. Se for um curinga ou se o naipe for o mesmo que declarou, você pode usar a ação Feitiço sem custo de ação, lançando um feitiço com custo total em PM igual ou menor que (NP × 5). Você ainda deve pagar esse custo de PM.', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Cartas Mágicas', 'Você recebe um baralho, uma mão e uma pilha de descarte. Durante um conflito, você pode usar uma ação e gastar até (10 + (NP × 5)) PM, mínimo de 10 PM. Se fizer isso, use o efeito de uma carta na sua mão para cada 5 PM gastos dessa forma, até o máximo de 5 cartas que formam um conjunto. Após usar o efeito do conjunto, se houver, descarte as cartas usadas e compre a mesma quantidade de cartas do seu baralho.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Dobro ou Nada', 'Antes de fazer um teste de Precisão, teste de Magia para um feitiço ofensivo ou teste para afetar um relógio, você pode declarar o dobro ou nada. Se fizer isso e rolar sucesso crítico, dobre o dano causado pelo ataque ou feitiço ou o número de seções preenchidas ou apagadas no relógio. Qualquer outro resultado é considerado falha.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Mulligan', 'No final do seu turno em um conflito, você pode descartar (NP) cartas da sua mão. Se fizer isso, compre a mesma quantidade de cartas do seu baralho.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Alma Ferida', 'Uma vez por cena, quando entra em crise, você pode criar um Laço de desconfiança com um número de inimigos igual a (NP) que você possa ver. Laços criados dessa forma duram até o fim da cena e não precisam apagar Laços preexistentes. Se seria necessário apagar Laços para criá-los, escolha um número de Laços atuais equivalente aos excedentes; esses Laços deixam de existir até o fim da cena.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Coração Ardente', 'Enquanto estiver sob o efeito de uma forma mágica, quando evoca um Laço de desconfiança, inferioridade e/ou ódio em um teste de Precisão ou Magia para causar dano, você causa (NP × 2) de dano adicional do mesmo tipo.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Impulso do Coração', 'O custo para usar Magitransformação é reduzido em um número de PM igual à quantidade de Laços com emoções de admiração, lealdade e/ou afeto que você possui, até o mínimo de 20 PM.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Magitransformação', 'Sempre que adquirir este poder, você deve criar uma nova forma mágica. Você pode usar uma ação e gastar 25 PM para assumir uma forma mágica que possui.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Transformação Aprimorada', 'Sempre que adquirir este poder, escolha a arma ou armadura de uma das suas formas mágicas. No fim de cada descanso, para cada item escolhido, você pode substituir sua característica ou aplicar uma nova, se o item não tiver características, como se fosse um item raro. A característica escolhida deve ser aprovada pelo mestre e ter valor em zênites igual ou menor que (40 × seu nível).', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Animar Arma', 'No seu turno, você pode usar uma ação e gastar 1 Ponto de Alma para animar uma arma equipada, liberando o espaço de mão ocupado por ela. A arma flutua como empunhada por uma mão invisível, perde multi e não pode recebê-la de nenhuma forma. No fim de cada rodada, essa arma faz um único ataque usando seu teste de Precisão, mas considera a RA como 0 ao calcular o dano. A arma permanece animada por um número de rodadas igual a (NP) ou até você animar outra arma.', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Coletar Almas', 'Você pode coletar Pontos de Alma de inimigos derrotados e usá-los para fortalecer seus poderes. Você não pode ter mais de (NP + 1) Pontos de Alma.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Forjar Característica', 'Você pode usar a ação Inventário e gastar 10 PM ou 1 Ponto de Alma para moldar uma característica de arma com custo de até (500z + (seu nível × 40z)) em uma arma ao seu alcance. A característica fica moldada até o fim da cena e um mesmo item só pode ter uma característica moldada por vez.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Forjar Feitiço', 'Sempre que adquirir este poder, escolha um feitiço ofensivo de elementalista. Você pode usar a ação Inventário e gastar 10 PM ou 1 Ponto de Alma para infundir um desses feitiços numa arma ao seu alcance. Até o fim da cena, um PJ equipado com uma arma com feitiço infundido pode fazer a ação Feitiço para lançar esse feitiço uma única vez, usando a fórmula do teste de Precisão da arma para o teste de Magia.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Manifestar Arma', 'No seu turno em um conflito, você pode usar a ação Equipamento e gastar 10 PM ou 1 Ponto de Alma para manifestar uma arma básica, destruindo qualquer arma já manifestada dessa forma. Se tiver espaços de mão livres, pode imediatamente equipar esta arma. Com ela, você pode trocar um Atributo do teste de Precisão por Vontade, como (VON + DES) para um arco curto.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Arsenal Vermelho', 'Você pode usar uma ação e gastar 5 PV para cobrir uma arma corpo a corpo equipada com seu próprio sangue até o fim da cena. A arma passa a disparar cortes de sangue que atingem alvos que não podem ser acertados por ataques corpo a corpo. Um alvo voador atingido por essa arma é forçado a pousar. Quando está em crise, você não gasta PV ao usar este poder e pode fazer um ataque livre como parte da mesma ação.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Dobrar Sangue', 'Você pode usar uma ação e gastar 20 PM para escolher um ataque básico ou feitiço conhecido de um inimigo que possa ver. Então faça um teste oposto contra ele de (VON + VIG). Se vencer, o alvo é obrigado a usar a ação escolhida no próximo turno contra um alvo à sua escolha.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Escudo Escarlate', 'Enquanto estiver em crise, sua Defesa e Defesa Mágica aumentam em (NP).', 'common', 0, 2, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Frenesi Sanguinolento', 'Quando rola um sucesso crítico ao fazer um ataque corpo a corpo, você pode gastar a oportunidade gerada para recuperar (NP × 10) PV.', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Hemofagia', 'Uma vez por rodada, quando outra criatura faz você perder PV, você pode gastar 10 PV para fazer um ataque livre contra essa criatura depois que a ação dela for resolvida. Se acertar, não causa o dano da arma; em vez disso causa (NP + RA do teste de Precisão) de dano físico.', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Engabelar', 'Uma vez por cena, quando um aliado ou inimigo que você possa ver faz um teste, você pode gastar 10 PM para convencer o destino a brincar com a sorte e o azar dele. Se fizer isso, faça o mesmo teste, mas com bônus ou penalidade, à sua escolha, igual a (NP). Então, você pode escolher trocar seu resultado com o resultado do alvo. Até o fim da cena, você pode usar o resultado trocado como a rolagem de um dos seus testes.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Explorar Fraqueza', 'No começo do seu turno, você pode gastar 10 PM para usar a ação Estudo sem custo de ação, antes ou depois da sua ação, usando (AST + DES) como fórmula do teste aberto.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Gambiarra', 'Uma vez por cena, você pode usar a ação Inventário e gastar até (NP × 2) PI para fazer uma modificação improvisada em uma arma equipada. Para cada 2 PI gastos, escolha uma modificação: a arma fornece +1 em testes de Precisão; causa 2 pontos de dano adicional; fornece +1 em testes da ação Objetivo; ou ataques com ela causam dano de veneno. As modificações duram até o fim da cena.', 'common', 0, 4, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Golpe Aproveitador', 'Quando faz um ataque contra uma única criatura que esteja sofrendo uma ou mais condições, você pode trocar um dos atributos do teste de Precisão da arma usada por DES e recebe bônus de (NP) nesse teste.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Jeitinho', 'Quando um aliado passar em um teste para preencher ou apagar seções de um relógio, você pode gastar até (NP × 20) PM. Se fizer isso, você não pode fazer testes para influenciar o relógio até o fim do seu próximo turno, mas preenche ou apaga uma seção desse relógio a cada 20 PM gastos dessa forma.', 'common', 0, 2, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Além do Reino da Morte', 'Quando outra criatura que você possa ver perde PV enquanto estiver em crise, se não for um morto-vivo, você recebe 1 Ponto de Túmulo. Você não pode ter mais de (NP + 1) Pontos de Túmulo. Ao ser reduzido a 0 PV, você perde todos os Pontos de Túmulo; se perdeu ao menos 1 ponto dessa forma e for a primeira vez que fica com 0 PV na cena, você não se rende nem se sacrifica: recupera PV igual a (NP × a quantidade de Pontos de Túmulo perdidos).', 'common', 0, 5, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Filhos da Sepultura', 'Você pode se comunicar verbalmente com mortos-vivos. Uma vez por cena, pode fazer uma pergunta a um morto-vivo, que deve responder sinceramente.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Medo é a Chave', 'Após fazer um ou mais inimigos perderem PV, se tiver Além do Reino da Morte e ao menos um desses inimigos estiver abalado e/ou fraco, você recebe 1 Ponto de Túmulo e recupera (NP × 2) PV e PM.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Por Quem os Sinos Dobram', 'Quando causa dano com um feitiço a uma criatura, se o feitiço causar dano apenas a ela, você pode gastar 1 Ponto de Túmulo. Se fizer isso, escolha um: se a criatura estiver sofrendo uma ou mais condições, o feitiço causa dano adicional igual a ((NP × 2) + o número de condições da criatura); ou, se a criatura não estiver sofrendo condições, ela fica abalada.', 'common', 0, 3, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Rondó do Pesadelo', 'Ao lançar um feitiço ofensivo com alvo “uma criatura”, você pode gastar 2 Pontos de Túmulo para atingir todas as criaturas presentes na cena que você possa ver. Faça um único teste de Magia e compare-o à Def.M de cada alvo. Se fizer isso, todo dano causado pelo feitiço torna-se de trevas e seu tipo não pode ser alterado.', 'common', 0, 1, NULL);
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Anatomista', 'Sempre que adquirir este poder heroico, escolha duas espécies entre construto, demônio, elemental, fera, monstro, morto-vivo e planta. Ao causar dano a um humanoide ou a uma criatura de uma das espécies escolhidas, você pode escolher um: causar 5 pontos de dano adicional a essa criatura; ou deixá-la desorientada até o fim da cena. Quando uma criatura desorientada recupera PV e/ou PM, ela recupera metade da quantidade normal e deixa de estar desorientada.', 'heroic', 0, 3, 'Dominar uma ou mais classes entre Atirador, Erudito, Furioso e Mestre de Armas.
Ter o poder Conhecimento é Poder');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Cancela do Lampião', 'Ao ser alvo de um poder ou feitiço do qual tenha sido alvo anteriormente nesta cena, você pode gastar 1 Ponto de Fabula para se tornar imune ao efeito e dano desse poder ou feitiço até o fim da cena ou até usar este poder novamente. Se gastar 1 Ponto de Ultima em vez do Ponto de Fabula, também recupera 20 PV.', 'heroic', 0, 1, 'Dominar a classe Bandoleiro');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Cargas Radiantes', 'Quando gerar cargas de qualquer tipo, você pode gastar 5 PM para transformar uma das cargas geradas em uma carga cósmica, que pode ser consumida como uma carga de qualquer tipo à sua escolha. Além disso, sempre que fizer uma criatura perder ou recuperar PV, você pode consumir uma carga cósmica para aumentar em 5 o número de PV perdidos ou recuperados.', 'heroic', 0, 1, 'Dominar a classe Astrólogo');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Ceifeiro do Pesar', 'Quando lança Drenar Espírito ou Drenar Vigor, a quantidade de PV ou PM que você recupera é respectivamente igual à perda de PM ou PV sofrida pelo alvo, em vez da metade. Além disso, se estiver no 20º nível ou acima, Drenar Espírito faz o alvo perder (RA + 20) PM em vez de (RA + 15); se estiver no 40º nível ou acima, faz perder (RA + 25) PM.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Entropista e Necromante.
Aprender ambos os feitiços Drenar Espírito e Drenar Vigor');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Constelação da Cruz Austral', 'Uma vez por cena, você pode usar uma ação, gastar 20 PM e consumir uma carga de cada tipo: celeste, estelar, meteórica e solar. Ao fazer isso, gera o efeito básico de cada um dos outros poderes de astrólogo que possui, cada um em um alvo diferente, sem usar ação ou gastar PM e sem gerar novas cargas.', 'heroic', 0, 1, 'Dominar a classe Astrólogo');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Corte Infernal', 'Ao usar Golpe das Sombras, você pode escolher fogo ou gelo. Se fizer isso, todo dano causado por este ataque torna-se do tipo escolhido em vez de trevas, e você torna-se Resistente ao tipo de dano não escolhido até o início de seu próximo turno. Ao fazer um ataque livre com uma arma corpo a corpo como parte de Golpe das Sombras, este ataque pode atingir inimigos que só podem ser escolhidos como alvos de ataques à distância.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Elementalista, Guerreiro Sombrio e Piloto.
Ter o poder Golpe das Sombras');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Dragão Empalador', 'Ao usar Golpe das Sombras, você pode considerar sua RA como 0 ao determinar o dano causado pelo ataque. Se fizer isso, após resolver o ataque de Golpe das Sombras, você pode imediatamente usar Carga de Cavalaria sem usar uma ação, pagando seu custo em PM.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Comandante e Guerreiro Sombrio.
Ter os poderes Carga de Cavalaria e Golpe das Sombras');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Está Vivo!', 'A Afinidade do seu companheiro a dano de raio torna-se Absorção e os PV máximos dele aumentam em (2 × seu NP em Visionário). Quando seu companheiro causar dano, se ele não tiver armas equipadas, causa dano adicional igual ao seu NP em Visionário.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Andarilho e Inventor.
Ter os poderes Companheiro Fiel (construto) e Visionário');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Fagomago', 'Quando lança Dissipar, o custo de PM desse feitiço torna-se 10 × A e o alvo torna-se até três criaturas. Ao fazer um ou mais inimigos deixarem de ser afetados por um ou mais feitiços com duração Cena, escolha um: recuperar 20 PM para cada feitiço cujos efeitos se encerraram em ao menos um inimigo dessa forma; ou, para cada feitiço assim, aplicar uma cópia do efeito desse feitiço em você mesmo, mantendo escolhas do feitiço original. Essa cópia não usa ações, PM ou testes e não é considerada lançar um feitiço.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Entropista, Gourmet, Mutante e Quimerista');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Fluxo de Yin e Yang', 'Ao causar dano físico, de gelo, de terra ou de trevas pela primeira vez em um turno, você recebe 1 Ponto de Yin e, se tiver pelo menos 1 Ponto de Yang, causa 5 pontos de dano adicional. Ao causar dano de ar, de fogo, de luz ou de raio pela primeira vez em um turno, você recebe 1 Ponto de Yang e, se tiver pelo menos 1 Ponto de Yin, causa 5 pontos de dano adicional. No fim de seu turno, se tiver 3 ou mais Pontos de Yin e/ou Yang e pelo menos 1 de cada tipo, perca todos esses pontos e aplique o efeito da maioria: Yin faz cada inimigo presente na cena perder PM igual à metade do seu nível; Yang faz uma criatura que você possa ver recuperar PM igual ao seu nível. Se empatar, aplique ambos. Você só ganha e usa esses pontos durante conflitos e os perde no fim de cada cena.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Astrólogo, Elementalista, Esper, Dançarino e Invocador');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Forja Entrelaçada', 'Você pode usar as ações Inventário ou Equipamento sem usar uma ação, mas apenas para usar um dos poderes de forjador de almas que possui.', 'heroic', 0, 1, 'Dominar a classe Forjador de Almas');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Instinto Assassino', 'Quando acerta uma criatura em crise com um ataque corpo a corpo, esse ataque causa 10 pontos de dano adicional. Se estiver no 40º nível ou acima, esse dano adicional aumenta para 20.', 'heroic', 0, 1, 'Dominar a classe Lâmina Carmesim');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Lido Como um Livro', 'Ao ter sucesso em Roubo de Alma contra um ou mais inimigos, você pode escolher um deles. Se fizer isso, faz a ação Estudo sem usar uma ação contra esse inimigo, considerando o resultado e a rolagem alta do teste aberto como iguais aos do teste feito para Roubo de Alma. Ao causar dano a um inimigo elite ou campeão, se você roubou o tesouro da alma dele durante esta cena, causa dano adicional igual ao seu NP em Roubo de Alma a esse inimigo.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Erudito, Esper, Ladino e Malandro.
Ter o poder Roubo de Alma');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Maestria de Ofuda', 'Ao usar Simbolismo em um conflito, você pode gastar 20 PM para ignorar o custo normal em PI deste poder. Ao fazer um ataque livre com uma arma corpo a corpo como parte do uso de Simbolismo, esse ataque pode atingir inimigos que só podem ser escolhidos como alvos de ataques à distância.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Arcanista, Mercador e Simbolista.
Ter o poder Simbolismo');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Mestre de Duelos', 'Ao usar o efeito de Par Mágico, se atacar com uma arma arcana ou arremessável, você causa dano adicional igual ao valor em comum das cartas resolvidas e recupera PM igual a 2 × esse valor.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Atirador, Carteador, Furioso, Ladino e Mestre de Armas.
Ter o poder Cartas Mágicas');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Multifunção', 'Quando uma criatura faz a ação Objetivo enquanto está equipada com uma ou mais armas com uma característica ou feitiço fornecida por um dos seus poderes de forjador de almas, ela recebe bônus de +1 no teste da ação para cada um desses itens, até o máximo de +2.', 'heroic', 0, 1, 'Dominar a classe Forjador de Almas');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Nascimento da Crueldade', 'Após a morte de um NPC que não seja vilão, que você possa ver e que seja fera, humanoide, monstro ou planta, você pode gastar 2 Pontos de Túmulo e reduzir seus PV e PM máximos em um número igual ao nível desse NPC. Se fizer isso, o cadáver se torna um lacaio morto-vivo de patente soldado que obedece a seus comandos telepáticos, retém equipamento original, tem turno próprio em conflitos e recebe benefícios de descanso. Se o lacaio ficar com 0 PV enquanto estiver a mais de um dia de viagem de você, ou se você morrer ou ficar inconsciente, ele é destruído. Você pode destruir seu lacaio a qualquer momento e, para criar outro, deve destruir o atual; se ele for destruído, seus PV e PM máximos voltam ao normal.', 'heroic', 0, 1, 'Dominar a classe Necromante');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Papinho Amigável', 'Durante uma cena de conflito, você pode usar uma ação para escolher uma criatura de patente soldado que possa ouvir e entender você, se o mestre disser que ela é um alvo válido. Se ela estiver sob duas ou mais condições, você pode gastar PM igual a (30 + metade do nível da criatura alvo) para convencê-la a lutar por você. Você controla a ficha dela no lugar do mestre. O efeito dura até o fim da cena ou até a criatura deixar de ter duas ou mais condições. Você só pode controlar uma criatura dessa forma por vez.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Malandro e Orador');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Poder da Amizade', 'Uma vez por cena, enquanto estiver sob o efeito de uma forma mágica, você pode gastar uma ação e PM igual a (10 × o número de PJs presentes na cena com os quais você tem um Laço) para fazer um ataque em grupo contra uma única criatura. Você e cada um desses personagens fazem um ataque livre contra essa criatura com uma arma equipada, considerando a RA do teste de Precisão como 0 ao calcular o dano. Após resolver os ataques, você causa dano adicional de luz ao alvo igual a 2 × a soma da força dos Laços que você tem com cada personagem que causou dano ao alvo. Se estiver no 20° nível ou acima, esse dano aumenta em 5; se estiver no 40° nível ou acima, aumenta em 10.', 'heroic', 0, 1, 'Dominar a classe Cavaleiro Mágico');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Preto e Branco', 'Ao usar o efeito de Encrenca em Dobro, você pode fazer todo o dano causado por ele tornar-se luz ou trevas, em vez de ser de um tipo correspondente aos naipes das cartas usadas. Além disso, enquanto tiver um curinga em sua pilha de descarte, todo dano causado por Encrenca em Dobro, Flush Mágico e Flush Ofuscante ignora Imunidades e Resistências.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Carteador, Entropista, Espiritualista e Guerreiro Sombrio.
Ter o poder Cartas Mágicas');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Pulso das Larvas', 'Enquanto tiver pelo menos 1 Ponto de Túmulo, você tem Imunidade a dano de trevas e veneno, Resistência a dano físico e Vulnerabilidade a dano de luz. Essas Afinidades substituem quaisquer outras que você tenha para esses tipos de dano e não podem ser alteradas enquanto você tiver pelo menos 1 Ponto de Túmulo.', 'heroic', 0, 1, 'Dominar a classe Necromante');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Raízes Simbióticas', 'Ao recuperar PV, você pode escolher recuperar apenas metade. Se fizer isso, seu companheiro recupera a mesma quantidade de PV. No fim de seu turno em um conflito, se os PV atuais do seu companheiro forem iguais ou maiores que os PV máximos dele e ele não tiver feito ações ou ataques neste turno, você pode ordenar que ele faça um ataque livre usando um dos ataques básicos que possui.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Andarilho, Floralista, Mutante e Quimerista.
Ter o poder Companheiro Fiel (construto)');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Redistribuição Aprimorada', 'O limite de Pontos de Ultima que você pode acumular com Redistribuir Riquezas aumenta para 3, mas você continua limitado a roubar somente 1 Ponto de Ultima por uso desse poder.', 'heroic', 0, 1, 'Dominar a classe Bandoleiro.
Ter o poder Redistribuir Riquezas');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Rito Proibido', 'Enquanto houver uma ou mais cartas em sua pilha de descarte, você tem Resistência ao tipo de dano correspondente ao naipe da carta no topo da pilha; se for um curinga, você tem Resistência a ar, fogo, gelo e terra. Você também adiciona o conjunto Monarca Proibido: 4 cartas do mesmo valor e nenhum curinga + 1 curinga. Seu efeito causa 777 pontos de dano a cada inimigo presente na cena; o dano é de luz se o valor em comum das 4 cartas for par, ou trevas se for ímpar. Se houver um curinga em sua pilha de descarte, esse dano ignora Imunidades e Resistências.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Arcanista e Carteador.
Ter adquirido pelo menos NP 3 em Cartas Mágicas');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Sacrifício Arcano', 'Uma vez por cena, quando você e/ou um ou mais aliados que você possa ver forem reduzidos a 0 PV, se você estiver fundido a um Arcano, em vez disso vocês podem ficar com exatamente 1 PV. Se fizer isso, você deve dispensar esse Arcano imediatamente, sem usar efeito de dispensar, e não pode invocá-lo novamente até o fim da cena.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Arcanista e Guardião');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Segredo do Grande Caldeirão', 'Quando criar uma poção por meio de Alquimia, você pode considerar que o resultado do dado que define o alvo é 13 ou 17, mesmo se o dado mostrar outro número.', 'heroic', 0, 1, 'Dominar a classe Inventor.
Ter o poder Engenhocas (Alquimia: superior)');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Tática da Asa Quebrada', 'Depois que um inimigo que você possa ver fizer um teste de Precisão ou de Magia para um feitiço ofensivo no turno dele em um conflito, você pode conceder +3 ao resultado desse teste. Se fizer isso, escolha um: você e cada aliado que possa escutá-lo tornam-se Resistentes a todos os tipos de dano até o fim deste turno; ou você e cada aliado que possa escutá-lo causam 5 pontos de dano adicional até o fim deste turno. Após usar este poder, você não pode reutilizá-lo até o início do seu próximo turno.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Comandante e Guardião');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Truque do Caçador', 'Ao transformar uma arma personalizada mutável durante seu turno, escolha um: se você não tiver feito ataques neste turno, o próximo ataque que fizer com esta arma neste turno causa 5 pontos de dano adicional; ou, se você atingir uma ou mais criaturas com um ataque usando esta arma neste turno, você recupera 5 PV e 5 PM.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Atirador e Mestre de Armas');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Vanguarda de Cartas', 'Durante um conflito, se você tiver duas ou menos cartas de vanguarda em jogo, pode usar uma ação para escolher 1 carta da sua mão e baixá-la como carta de vanguarda com a face para baixo; se fizer isso, compre 1 carta do seu baralho. Ao sofrer dano, se tiver uma ou mais cartas de vanguarda em jogo, você pode revelar uma delas e colocá-la no topo da pilha de descarte. Se a carta for curinga ou seu naipe corresponder ao tipo de dano sofrido, você não sofre dano e recupera PM igual ao dano que sofreria. No fim de cada conflito, embaralhe cartas de vanguarda de volta no baralho.', 'heroic', 0, 1, 'Dominar a classe Carteador.
Ter o poder Cartas Mágicas');
INSERT OR IGNORE INTO job_powers (name, description, type, is_global, max_level, prerequisites) VALUES ('Voz da Bruxaria', 'Após um ou mais inimigos sofrerem uma ou mais condições devido a um verso que você cantou ou ao seu Condenar, cada um desses inimigos também fica enfeitiçado, exceto criaturas imunes ou que já sofriam todas as condições que podem ser infligidas dessa forma. Uma criatura enfeitiçada deve sempre incluir você entre os alvos de ataques e feitiços ofensivos se puder, e deixa de estar enfeitiçada no início de seu próximo turno ou assim que se recuperar de uma ou mais condições.', 'heroic', 0, 1, 'Dominar uma ou mais classes entre Orador e Virtuoso');
